from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            fillForward=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .CallsOnly()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_minutes = {}

        self.entry_ticket = None
        self.entry_price = None
        self.held_symbol = None
        self.exit_ticket = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        if self.bucket_date is not None and self.bucket_date != current_date:
            self._finalize_bucket()
            self.bucket_date = None
            self.bucket_start = None
            self.bucket_minutes = {}

        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.no_entry_today = True
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity position.")
            self.MarketOrder(
                self.spy.Symbol,
                -self.Portfolio[self.spy.Symbol].Quantity
            )

        self._process_option_exit(slice)

        if slice.Bars.ContainsKey(self.spy.Symbol):
            bar = slice.Bars[self.spy.Symbol]
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time.time()
        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute_offset = (bar.Time.hour * 60 + bar.Time.minute) - (9 * 60 + 30)
        bucket_minute = 9 * 60 + 30 + (minute_offset // 5) * 5
        bucket_start = datetime(
            bar.Time.year,
            bar.Time.month,
            bar.Time.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.bucket_start is None:
            self.bucket_date = bar.Time.date()
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self._finalize_bucket()
            self.bucket_start = bucket_start
            self.bucket_minutes = {}

        self.bucket_minutes[bar.Time] = bar.Close

    def _finalize_bucket(self):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self.bucket_minutes for t in expected_times):
            self.bucket_minutes = {}
            return

        close = self.bucket_minutes[expected_times[-1]]
        end_time = self.bucket_start + timedelta(minutes=5)

        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.closes.append(close)
        if len(self.closes) > 20:
            self.closes.pop(0)

        current_fast = None
        current_slow = None
        if len(self.closes) >= 5:
            current_fast = sum(self.closes[-5:]) / 5.0
        if len(self.closes) >= 20:
            current_slow = sum(self.closes[-20:]) / 20.0

        bullish_crossover = (
            prior_fast is not None and
            prior_slow is not None and
            current_fast is not None and
            current_slow is not None and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_minutes = {}

        end_clock = end_time.time()
        if (
            bullish_crossover and
            time(9, 45) <= end_clock <= time(14, 30)
        ):
            self._try_entry(self._current_slice, close)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_symbol = self.entry_ticket.Symbol
                self.Debug(
                    f"Entered {self.held_symbol} at {self.entry_price:.4f}"
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exited {self.exit_ticket.Symbol}.")
                self.exit_ticket = None
                self.entry_price = None
                self.held_symbol = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = bool(getattr(order_event, "IsExercise", False))
        if is_assignment or is_exercise:
            self.no_entry_today = True
            self.Debug("Unexpected option exercise or assignment processed.")

    def _try_entry(self, slice: Slice, spy_price: float):
        if self.no_entry_today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying option expiration.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() == selected_expiry and
            contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        contract = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_today = True
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if not slice.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._submit_exit("profit target")

    def _submit_exit(self, reason: str):
        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.CancelOrder(self.exit_ticket.OrderId)

        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity > 0:
            self.Debug(f"Submitting exit for {reason}: {self.held_symbol}.")
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _order_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

