from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_PCT = 0.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw,
            extended_market_hours=False
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=20)
        self.bucket_start = None
        self.bucket_closes = {}

        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_fill_price = None
        self.no_entry_dates = set()

    def OnData(self, data: Slice):
        today = self.Time.date()

        # Immediately remove any unexpected SPY equity position.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected SPY exercise/assignment position detected; liquidating."
            )
            self.Liquidate(self.spy)
            self.no_entry_dates.add(today)

        self._process_option_exits(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, data)

    def _process_minute_bar(self, bar: TradeBar, data: Slice):
        end_time = bar.EndTime.replace(tzinfo=None, second=0, microsecond=0)
        local_date = end_time.date()

        if not (datetime.combine(local_date, datetime.min.time()) +
                timedelta(hours=9, minutes=30) <= end_time <=
                datetime.combine(local_date, datetime.min.time()) +
                timedelta(hours=16)):
            return

        minutes_from_open = int(
            (end_time - datetime.combine(
                local_date, datetime.min.time()
            ) - timedelta(hours=9, minutes=30)).total_seconds() / 60
        )

        bucket_number = minutes_from_open // 5
        bucket_start = datetime.combine(
            local_date, datetime.min.time()
        ) + timedelta(hours=9, minutes=30 + bucket_number * 5)

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_five_minute_bar(self.bucket_start, data)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_closes = {}

        minute_offset = int((end_time - bucket_start).total_seconds() / 60)
        if 1 <= minute_offset <= 5:
            self.bucket_closes[minute_offset] = bar.Close

    def _complete_five_minute_bar(self, bucket_start: datetime, data: Slice):
        # Require all five minute bars; never synthesize missing data.
        if set(self.bucket_closes.keys()) != {1, 2, 3, 4, 5}:
            self.bucket_closes = {}
            return

        close = self.bucket_closes[5]
        previous_fast = None
        previous_slow = None

        if len(self.fast_closes) >= 20:
            previous_fast = sum(list(self.fast_closes)[-5:]) / 5.0
            previous_slow = sum(self.fast_closes) / 20.0

        self.fast_closes.append(close)

        if len(self.fast_closes) < 20:
            self.bucket_closes = {}
            return

        current_fast = sum(list(self.fast_closes)[-5:]) / 5.0
        current_slow = sum(self.fast_closes) / 20.0

        eligible_time = (
            bucket_start + timedelta(minutes=5)
        ).time()
        eligible = (
            datetime.strptime("09:45", "%H:%M").time()
            <= eligible_time
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross and eligible:
            self._try_enter(data)

        self.bucket_closes = {}

    def _try_enter(self, data: Slice):
        today = self.Time.date()

        if today in self.no_entry_dates:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(
            self.entry_ticket
        ):
            return

        chains = getattr(data, "OptionChains", None)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = self.Securities[self.spy].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in contracts
        )
        strike_floor = current_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted entry market order for {}".format(selected.Symbol))

    def _process_option_exits(self, data: Slice):
        if self.held_option is None:
            return

        today = self.Time.date()
        option_holding = self.Portfolio[self.held_option]

        if option_holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        # Never intentionally carry the option into its expiration date.
        if today >= expiry_date:
            self.no_entry_dates.add(today)
            self._submit_exit("expiration processing")
            return

        # Time stop on the trading day immediately preceding expiration.
        preceding_day = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            preceding_day
        ):
            preceding_day -= timedelta(days=1)

        if today == preceding_day and self.Time.time() >= datetime.strptime(
            "15:45", "%H:%M"
        ).time():
            self._submit_exit("expiration time stop")
            return

        if self.exit_ticket is not None and not self._ticket_finished(
            self.exit_ticket
        ):
            return

        contract = None
        chains = getattr(data, "OptionChains", None)
        if chains:
            for chain in chains:
                for candidate in chain:
                    if candidate.Symbol == self.held_option:
                        contract = candidate
                        break
                if contract is not None:
                    break

