        target = self.entry_fill_price * (1.0 + self.PROFIT_TARGET_PCT)

        if self.entry_fill_price > 0 and midpoint >= target:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

