            self.exit_ticket
        ):
            return

        if self.entry_ticket is not None and not self._ticket_finished(
            self.entry_ticket
        ):
            return

        if self.Portfolio[self.held_option].Quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )
        self.Debug(
            "Submitted exit market order for {}: {}".format(
                self.held_option, reason
            )
        )

