            self.current_bucket = bucket_key

        self.bucket_bars[minute_of_day] = minute_bar

        if minute_of_day == bucket_end_minute:
            self._emit_bucket(bucket_key, slice)
            self.bucket_bars = {}
            self.current_bucket = None

    def _emit_bucket(self, bucket_end: datetime, slice: Slice):
        expected = []
        for offset in range(5, 0, -1):
            expected.append(bucket_end.hour * 60 + bucket_end.minute - offset)

        if any(minute not in self.bucket_bars for minute in expected):
            return

        bars = [self.bucket_bars[minute] for minute in expected]
        start = bucket_end - timedelta(minutes=5)

        consolidated = TradeBar(
            start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = consolidated.EndTime.time()
        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        if bullish_cross and eligible_start <= end_time <= eligible_end:
            self._evaluate_entry(slice, consolidated)

    def _evaluate_entry(self, slice: Slice, spy_bar: TradeBar):
        if self.entry_order_id is not None or self.held_symbol is not None:
            return

        current_date = self.Time.date()
        if self.no_entry_date == current_date:
            return

        if self.option not in slice.OptionChains:
            self.Debug("Skipped call selection: no option chain")
            return

        chain = slice.OptionChains[self.option]
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no eligible expiration")
            return

        selected_expiry = expiries[0]
        underlying_price = spy_bar.Close
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.AddOptionContract(selected.Symbol, Resolution.Minute)

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId

    def _evaluate_exit(self, slice: Slice, current_date, expiry_date):
        if self.held_symbol is None:
            return

        if self._is_immediately_pre_expiration_trading_day(
            current_date, expiry_date
        ) and self.Time.time() >= time(15, 45):
            self._submit_exit("pre-expiration time stop")
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        bid = quote.Bid.Close if quote.Bid is not None else None
        ask = quote.Ask.Close if quote.Ask is not None else None

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if self.entry_price is not None:
            target = self.entry_price * (1 + self.profit_target_percent)
            if midpoint >= target:
                self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag="Option exit: " + reason
        )
        self.Debug("Submitted option exit for {}: {}".format(
            self.held_symbol, reason
        ))

    def _handle_unexpected_equity_position(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY equity; "
                "liquidating entire SPY position"
            )
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Unexpected exercise or assignment cleanup"
            )
            self.no_entry_date = self.Time.date()

    def _is_immediately_pre_expiration_trading_day(
        self, current_date, expiry_date
    ):
        candidate = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return current_date == candidate

    @staticmethod
    def _is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(order_event.Message).lower()
        if "exercise" in message or "assignment" in message:
