        self.exit_order = None
        self.held_contract = None
        self.entry_fill_price = None
        self.expiration_block_date = None
        self.assignment_liquidation_submitted = False

        # Profit target is a 50% gain over the filled option entry price.
        self.profit_target_multiple = 1.50

    def OnData(self, slice: Slice):
        now = self.Time
        current_date = now.date()

        self._handle_unexpected_equity_position()

        if self.held_contract is not None:
            expiry_date = self.held_contract.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_block_date = current_date
                self.Debug(
                    "Expiration processing: liquidating {}".format(
                        self.held_contract.Value
                    )
                )
                self._submit_exit("expiration")
            else:
                previous_trading_day = self._previous_trading_day(expiry_date)
                if (
                    current_date == previous_trading_day
                    and now.time() >= time(15, 45)
                ):
                    self.expiration_block_date = current_date
                    self._submit_exit("time stop")
                else:
                    self._evaluate_profit_target(slice)

        if self.spy_symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy_symbol]
        completed_bar = self._update_five_minute_bar(minute_bar)

        if completed_bar is None:
            return

        if (
            self.entry_order is not None
            or self.held_contract is not None
            or self.expiration_block_date == current_date
        ):
            return

        bar_end = completed_bar[0]
        close = completed_bar[1]

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

            self.closes.append(close)

            current_values = list(self.closes)
            current_fast = sum(current_values[-5:]) / 5.0
            current_slow = sum(current_values) / 20.0

            bullish_crossover = (
                previous_fast <= previous_slow
                and current_fast > current_slow
            )

            if bullish_crossover:
                self._try_enter(slice, close)
        else:
            self.closes.append(close)

