        local_time = minute_bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.astimezone().replace(tzinfo=None)

        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return None

        bucket_index = (local_time.hour * 60 + local_time.minute - 570) // 5
        bucket_start_minutes = 570 + bucket_index * 5
        bucket_start = datetime.combine(
            local_time.date(), time(0, 0)
        ) + timedelta(minutes=bucket_start_minutes)

        if self.current_bucket is None:
            self.current_bucket = bucket_start
            self.bucket_date = local_time.date()
        elif bucket_start != self.current_bucket:
            result = None

            if (
                self.bucket_date == self.current_bucket.date()
                and len(self.bucket_closes) == 5
            ):
                result = (
                    self.current_bucket + timedelta(minutes=5),
                    self.bucket_closes[-1]
                )

            self.current_bucket = bucket_start
            self.bucket_date = local_time.date()
            self.bucket_closes = []

            if result is not None:
                self.closes.append(result[1])
                return result

        if local_time.date() != self.bucket_date:
            self.bucket_closes = []

        self.bucket_closes.append(float(minute_bar.Close))
        return None

    def _try_enter(self, slice, spy_price):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

