        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_order = self.MarketOrder(selected.Symbol, 1)

        if self.entry_order is not None:
            self.Debug(
                "Entry submitted: {} expiry {} strike {}".format(
                    selected.Symbol.Value,
                    selected_expiry,
                    selected.Strike
                )
            )

    def _evaluate_profit_target(self, slice):
        if self.entry_fill_price is None or self.exit_order is not None:
            return

        symbol = self.held_contract.Symbol
        quote = slice.QuoteBars.get(symbol)

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= self.entry_fill_price * self.profit_target_multiple:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_contract is None or self.exit_order is not None:
            return

        symbol = self.held_contract.Symbol
        quantity = self.Portfolio[symbol].Quantity

        if quantity <= 0:
            return

        self._cancel_open_exit_order()
        self.exit_order = self.MarketOrder(symbol, -quantity)
        self.Debug("Exit submitted: {} ({})".format(symbol.Value, reason))

    def _cancel_open_exit_order(self):
        if self.exit_order is not None:
            status = self.exit_order.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                self.exit_order.Cancel("Replaced by liquidation order")

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_order is not None
                and order_event.OrderId == self.entry_order.OrderId
            ):
                self.held_contract = self.Securities[order_event.Symbol]
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order = None

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol.Value,
                        self.entry_fill_price
                    )
                )

            elif (
                self.exit_order is not None
                and order_event.OrderId == self.exit_order.OrderId
            ):
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        order_event.Symbol.Value,
                        float(order_event.FillPrice)
                    )
                )
                self.exit_order = None
                self.held_contract = None
                self.entry_fill_price = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            if (
                self.entry_order is not None
                and order_event.OrderId == self.entry_order.OrderId
            ):
                self.Debug("Entry order {}".format(order_event.Status))
                self.entry_order = None

            if (
                self.exit_order is not None
                and order_event.OrderId == self.exit_order.OrderId
            ):
                self.exit_order = None

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy_symbol]

        if holding.Invested and not self.assignment_liquidation_submitted:
            self.assignment_liquidation_submitted = True
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity"
            )
            self.MarketOrder(self.spy_symbol, -holding.Quantity)

        if not holding.Invested:
            self.assignment_liquidation_submitted = False

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

