            )
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy_symbol, -quantity, tag="Unexpected exercise or assignment"
            )

    def GetCurrentQuote(self, slice, symbol):
        if slice.OptionChains is not None:
            for chain in slice.OptionChains.Values:
                for contract in chain:
                    if contract.Symbol == symbol:
                        return contract.BidPrice, contract.AskPrice

        if slice.QuoteBars is not None and symbol in slice.QuoteBars:
            quote = slice.QuoteBars[symbol]
            if quote.Bid is not None and quote.Ask is not None:
                return quote.Bid.Close, quote.Ask.Close

        return None

    def GetPreviousTradingDay(self, date_value):
        date_time = datetime.combine(date_value, datetime.min.time())
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        return exchange_hours.GetPreviousTradingDay(date_time).date()

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None
            and self.IsOrderOpen(self.entry_ticket)
        )

    def IsOrderOpen(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )
