from datetime import datetime, timedelta

from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Orders import OrderStatus
from QuantConnect.Securities import DataNormalizationMode, Resolution
from QuantConnect.Securities.Option import OptionRight


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = []
        self.slow_closes = []

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.held_symbol = None
        self.exit_ticket = None
        self.no_entry_date = None

        # The specification does not provide a numeric target.
        self.profit_target_multiplier = 1.20

    def OnData(self, slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()
        self._evaluate_open_position(slice)

        if self._entry_order_is_open() or self._option_position_exists():
            self._process_spy_bar(slice)
            return

        if self.no_entry_date == today:
            self._process_spy_bar(slice)
            return

        self._process_spy_bar(slice)

    def _process_spy_bar(self, slice):
        if not slice.Bars.ContainsKey(self.spy_symbol):
            return

        bar = slice.Bars[self.spy_symbol]
        endpoint = self.Time.replace(second=0, microsecond=0)

        if endpoint.hour < 9 or endpoint.hour > 16:
            return
        if endpoint.hour == 9 and endpoint.minute < 31:
            return
        if endpoint.hour == 16 and endpoint.minute > 0:
            return

        if self.bucket_date != endpoint.date():
            self.bucket_date = endpoint.date()
            self.bucket_end = None
            self.bucket_closes = {}

        bucket_minute = ((endpoint.minute + 4) // 5) * 5
        bucket_hour = endpoint.hour

        if bucket_minute >= 60:
            bucket_hour += 1
            bucket_minute -= 60

        new_bucket_end = endpoint.replace(
            hour=bucket_hour,
            minute=bucket_minute,
            second=0,
            microsecond=0,
        )

        if self.bucket_end is not None and new_bucket_end != self.bucket_end:
            if len(self.bucket_closes) == 5:
                self._process_completed_bar(
                    self.bucket_end,
                    self.bucket_closes[self.bucket_end],
                    slice,
                )
            self.bucket_closes = {}

        self.bucket_end = new_bucket_end

        if endpoint not in self.bucket_closes:
            self.bucket_closes[endpoint] = float(bar.Close)

        if len(self.bucket_closes) == 5 and endpoint == self.bucket_end:
            self._process_completed_bar(
                self.bucket_end,
                self.bucket_closes[endpoint],
                slice,
            )
            self.bucket_closes = {}

    def _process_completed_bar(self, bar_end, close, slice):
        if len(self.slow_closes) >= 20:
            previous_fast = sum(self.fast_closes[-5:]) / 5.0
            previous_slow = sum(self.slow_closes[-20:]) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) > 5:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)

        if previous_fast is None:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        eligible_time = (
            bar_end.time() >= datetime.strptime("09:45", "%H:%M").time()
            and bar_end.time() <= datetime.strptime("14:30", "%H:%M").time()
        )

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_crossover:
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self._entry_order_is_open() or self._option_position_exists():
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        spy_price = float(self.Securities[self.spy_symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        chains = list(slice.OptionChains.Values)

        expirations = sorted(
            {
                contract.Expiry.date()
                for chain in chains
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for chain in chains
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol)),
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )

    def _evaluate_open_position(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0 or self._exit_order_is_open():
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiplier:
            self._submit_exit("Profit target exit")

    def _handle_expiration_processing(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("Expiration protection exit")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if today == previous_trading_day and self.Time.time() >= datetime.strptime(
            "15:45", "%H:%M"
        ).time():
            self._submit_exit("Pre-expiration time stop")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_orders()
        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: " + reason)

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.Debug("Unexpected exercise or assignment; liquidating SPY.")
            self.Liquidate(self.spy_symbol, tag="Unexpected exercise or assignment")
            self.no_entry_date = self.Time.date()

    def _cancel_open_exit_orders(self):
        if self.held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if self.exit_ticket is None or order.Id != self.exit_ticket.OrderId:
                self.Transactions.CancelOrder(
                    order.Id,
                    "Canceled before replacement exit order",
                )

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _option_position_exists(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity > 0
        )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.held_symbol = self.entry_symbol
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_price)
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Option exit filled: " + str(self.held_symbol))
            self.held_symbol = None
            self.entry_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

        message = str(getattr(order_event, "Message", "")).lower()
        if "assignment" in message or "exercise" in message:
