from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillDataForward=False,
            leverage=1,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self._bucket_end = None
        self._bucket_valid = True
        self._bucket_count = 0
        self._bucket_open = None
        self._bucket_high = None
        self._bucket_low = None
        self._bucket_close = None
        self._last_minute_end = None

        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.time_stop_date = None
        self.no_entry_date = None

        # A 50% gain is the profit target.
        self.profit_target_multiple = 1.50

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_expiration_safety()

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar)

        self._process_option_exit(slice)

    def _process_minute_bar(self, bar: TradeBar):
        end = bar.EndTime
        session_start = datetime.combine(end.date(), time(9, 30))
        session_end = datetime.combine(end.date(), time(16, 0))

        if end <= session_start or end > session_end:
            return

        bucket_number = int((end - session_start).total_seconds() // 300)
        bucket_end = session_start + timedelta(minutes=(bucket_number + 1) * 5)

        if self._bucket_end != bucket_end:
            self._complete_bucket()

            self._bucket_end = bucket_end
            self._bucket_valid = True
            self._bucket_count = 0
            self._bucket_open = None
            self._bucket_high = None
            self._bucket_low = None
            self._bucket_close = None

            if self._last_minute_end is not None:
                if end - self._last_minute_end != timedelta(minutes=1):
                    self._bucket_valid = False

        elif self._last_minute_end is not None:
            if end - self._last_minute_end != timedelta(minutes=1):
                self._bucket_valid = False

        self._last_minute_end = end
        self._bucket_count += 1

        if self._bucket_open is None:
            self._bucket_open = bar.Open
            self._bucket_high = bar.High
            self._bucket_low = bar.Low
        else:
            self._bucket_high = max(self._bucket_high, bar.High)
            self._bucket_low = min(self._bucket_low, bar.Low)

        self._bucket_close = bar.Close

    def _complete_bucket(self):
        if (
            self._bucket_end is None
            or self._bucket_count != 5
            or not self._bucket_valid
            or self._bucket_close is None
        ):
            return

        self.fast_window.Add(float(self._bucket_close))
        self.slow_window.Add(float(self._bucket_close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        bar_end = self._bucket_end
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        fast_current = sum(self.fast_window) / self.fast_window.Count
        slow_current = sum(self.slow_window) / self.slow_window.Count

        if self.fast_window.Count < 2 or self.slow_window.Count < 2:
            return

        fast_previous = sum(
            self.fast_window[i] for i in range(1, self.fast_window.Count)
        ) / (self.fast_window.Count - 1)
        slow_previous = sum(
            self.slow_window[i] for i in range(1, self.slow_window.Count)
        ) / (self.slow_window.Count - 1)

        bullish_cross = (
            fast_previous <= slow_previous
            and fast_current > slow_current
        )

        if bullish_cross:
            self._try_enter()

    def _try_enter(self):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_option is not None:
            if self.Portfolio[self.held_option].Invested:
                return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        chains = self.CurrentSlice.OptionChains
        if chains is None or len(chains) == 0:
            self.Debug("Skipped entry: no option chain")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no eligible call expiration")
            return

        selected_expiry = min(contract.Expiry.date() for contract in candidates)
        strike_floor = spy_price * 1.01

        strike_candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no eligible strike")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.held_option, 1)

        self.time_stop_date = self._previous_trading_day(selected.Expiry)
        self.Debug("Entry submitted: {}".format(self.held_option))

    def _process_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        today = self.Time.date()

        if today >= self.held_option_expiry_date():
            self.no_entry_date = today
            self._submit_exit("expiration safety")
            return

        if (
            self.time_stop_date is not None
            and today == self.time_stop_date
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        bid = None
        ask = None

        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    break
            if bid is not None:
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiple:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")
            self.Debug("Exit order canceled: {}".format(reason))

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                if not self.Portfolio[self.held_option].Invested:
                    self.held_option = None
                    self.entry_price = None
                    self.time_stop_date = None
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Tag))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.time_stop_date = None

    def _process_expiration_safety(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option_expiry_date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.held_option].Invested:
                self._submit_exit("expiration safety")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise or assignment; liquidating SPY")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.no_entry_date = self.Time.date()

    def held_option_expiry_date(self):
        security = self.Securities.get(self.held_option)
        if security is not None and security.Symbol.ID.Date != datetime.min:
            return security.Symbol.ID.Date.date()

        if self.held_option is not None:
            for chain in self.CurrentSlice.OptionChains:
                for contract in chain:
                    if contract.Symbol == self.held_option:
                        return contract.Expiry.date()

        return self.Time.date()

    def _previous_trading_day(self, expiry):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        date = expiry - timedelta(days=1)

        while not exchange_hours.IsDateOpen(date):
            date -= timedelta(days=1)

        return date.date()

