from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    PROFIT_TARGET_PERCENT = 0.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.spy_option.Symbol
        self.spy_option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.consolidator
        )

        self.closes = RollingWindow[float](20)
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self.HandleUnexpectedSpyPosition(today)
        self.HandleExpirationProcessing(today)

        held_symbol = self.GetHeldOptionSymbol()
        if held_symbol is not None:
            self.EvaluateExit(held_symbol, slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar is None:
            return

        bar_end = bar.EndTime.time()
        previous_fast = None
        previous_slow = None

        if self.closes.Count >= 20:
            previous_fast = sum(self.closes[i] for i in range(5)) / 5.0
            previous_slow = sum(self.closes[i] for i in range(20)) / 20.0

        self.closes.Add(float(bar.Close))

        if self.closes.Count < 20:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.GetHeldOptionSymbol() is not None:
            return

        if self.IsEntryOrderOpen():
            return

        self.SelectAndEnterCall()

    def SelectAndEnterCall(self):
        chain = self.CurrentSlice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        expiration_date = min(
            contract.Expiry.date() for contract in eligible
        )

        current_price = float(self.Securities[self.spy_symbol].Price)
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiration_date
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at the selected expiration."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                self.entry_symbol,
                expiration_date,
                selected.Strike
            )
        )

    def EvaluateExit(self, symbol: Symbol, slice: Slice):
        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        holding = self.Portfolio[symbol]
        if not holding.Invested:
            return

        today = self.Time.date()
        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()

        if today >= expiry_date:
            self.SubmitExit(symbol, "expiration processing")
            self.no_entry_date = today
            return

        previous_trading_day = self.GetPreviousTradingDay(expiry_date)

        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit(symbol, "expiration time stop")
            return

        if self.entry_price is None:
            return

        quote = self.GetCurrentQuote(symbol, slice)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_price * (
            1.0 + self.PROFIT_TARGET_PERCENT
        )

        if midpoint >= target_price:
            self.SubmitExit(symbol, "profit target")

    def SubmitExit(self, symbol: Symbol, reason: str):
        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = -self.Portfolio[symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(symbol, quantity)
        self.Debug("Exit submitted: {} ({})".format(symbol, reason))

    def GetCurrentQuote(self, symbol: Symbol, slice: Slice):
        if symbol in slice.QuoteBars:
            quote_bar = slice.QuoteBars[symbol]
            if quote_bar.Bid is not None and quote_bar.Ask is not None:
                return (
                    float(quote_bar.Bid.Close),
                    float(quote_bar.Ask.Close)
                )

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return (
                        float(contract.BidPrice),
                        float(contract.AskPrice)
                    )

        return None

    def HandleExpirationProcessing(self, today):
        symbol = self.GetHeldOptionSymbol()
        if symbol is None:
            return

        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()
        if today >= expiry_date:
            self.no_entry_date = today
            self.SubmitExit(symbol, "expiration processing")

    def HandleUnexpectedSpyPosition(self, today):
        if self.Portfolio[self.spy_symbol].Invested:
            self.no_entry_date = today
            self.Liquidate(
                self.spy_symbol,
                "Unexpected SPY position from exercise or assignment"
            )
            self.Debug(
                "Unexpected exercise or assignment handling: "
                "liquidating SPY equity position."
            )

    def GetHeldOptionSymbol(self):
        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested:
                return self.entry_symbol

        for security in self.Portfolio.Values:
            symbol = security.Symbol
            if (
                symbol.SecurityType == SecurityType.Option
                and security.Invested
            ):
                return symbol

        return None

    def IsEntryOrderOpen(self):
        return self.entry_ticket is not None and self.IsOrderOpen(
            self.entry_ticket
        )

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.NoneStatus,
        )

    def GetPreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.FillQuantity > 0
        ):
            if self.entry_price is None:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} price={}".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} price={}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self.exit_ticket = None
            self.entry_symbol = None
            self.entry_price = None

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected exercise or assignment event received; "
                "strategy entries disabled for today."
            )
            if self.Portfolio[self.spy_symbol].Invested:
                self.Liquidate(
                    self.spy_symbol,
                    "Liquidating SPY after assignment"
                )

