        if symbol in slice.QuoteBars:
            quote_bar = slice.QuoteBars[symbol]
            if quote_bar.Bid is not None and quote_bar.Ask is not None:
                return (
                    float(quote_bar.Bid.Close),
                    float(quote_bar.Ask.Close)
                )

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return (
                        float(contract.BidPrice),
                        float(contract.AskPrice)
                    )

        return None

