        symbol = self.GetHeldOptionSymbol()
        if symbol is None:
            return

        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()
        if today >= expiry_date:
            self.no_entry_date = today
            self.SubmitExit(symbol, "expiration processing")

