        bucket_end_minute = ((minute + 4) // 5) * 5
        if bucket_end_minute == 60:
            bucket_end_minute = 0

        bucket_end = local_time.replace(
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )

        if bucket_end_minute == 0:
            bucket_end += timedelta(hours=1)

        if self.bucket_end != bucket_end:
