            previous_time = local_time - timedelta(minutes=1)
            if previous_time.minute != minute - 1 and not (
                minute == 0 and previous_time.minute == 59
            ):
                self.bucket_valid = False

        self.bucket_prices.append(bar.Close)

        if local_time.minute != bucket_end.minute or local_time.hour != bucket_end.hour:
