        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(
                list(self.closes)[-self.fast_period:]
            ) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(
            list(self.closes)[-self.fast_period:]
        ) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        eligible_time = (
            (local_time.hour > 9 or
             (local_time.hour == 9 and local_time.minute >= 45))
            and (
                local_time.hour < 14 or
                (local_time.hour == 14 and local_time.minute <= 30)
            )
        )

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

