            return

        contract = self.GetHeldContract(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_price * (
            1.0 + self.profit_target_percent / 100.0
        )

        if midpoint >= target_price:
            self.SubmitExit("Profit target reached.")

