        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                return contract
        return None

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket.Cancel("Replacing open exit order.")
                return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Submitted option exit for {}: {}".format(
                self.held_option,
                reason
            )
        )

    def ProcessExpirationEve(self):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        next_market_open = self.Securities[
            self.spy.Symbol
        ].Exchange.Hours.GetNextMarketOpen(self.Time, False)

        if next_market_open.date() == expiry:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("Expiration-eve time stop.")

    def ProcessExpiration(self):
        self.no_entry_date = self.Time.date()

        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        if expiry <= self.Time.date():
            self.SubmitExit("Expiration processing liquidation.")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy.Symbol]
        if holding.Quantity != 0:
            self.Debug(
                "Unexpected SPY exercise or assignment position detected."
            )
            self.Liquidate(
                self.spy.Symbol,
                tag="Unexpected exercise or assignment handling"
            )
            self.no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option assignment or exercise detected.")
            self.Liquidate(
                self.spy.Symbol,
                tag="Unexpected exercise or assignment handling"
            )
            self.no_entry_date = self.Time.date()

        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Call entry filled: {} at {}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Call entry order did not fill.")
                self.entry_ticket = None
                self.entry_order_id = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Call exit filled: {} at {}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

    def OnEndOfAlgorithm(self):
        if self.held_option is not None:
            self.Debug("Unexpected option holding remained at algorithm end.")

