        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None

        self.no_entries_today = False
        self.blocked_date = None
        self.spy_cleanup_submitted = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.blocked_date != current_date:
            self.blocked_date = current_date
            self.no_entries_today = False
            self.spy_cleanup_submitted = False

        self._handle_unexpected_spy_position()
        self._process_expiration()

        spy_bar = self._get_data(slice.Bars, self.spy)
        if spy_bar is not None:
            self._process_spy_minute(spy_bar)

        self._evaluate_option_exit(slice)

        if self.pending_signal:
            self.pending_signal = False

            if self.no_entries_today:
                return

            if self.held_option is not None:
                return

            if self._has_open_entry_order() or self._has_option_holding():
                return

            self._enter_from_current_chain(slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} @ {:.4f}".format(
                        self.held_option, self.entry_fill_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                if order_event.Status != OrderStatus.None_:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self.exit_ticket.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_fill_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

    def _process_spy_minute(self, bar):
        bar_time = bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute_index = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        bucket_index = minute_index // 5
        bucket_start_minutes = 9 * 60 + 30 + bucket_index * 5
        bucket_start = time(bucket_start_minutes // 60, bucket_start_minutes % 60)

        if self.bucket_date != bar_time.date() or self.bucket_start != bucket_start:
            if self.bucket_date == bar_time.date() and self.bucket_start is not None:
                self._finalize_five_minute_bar()

            self.bucket_date = bar_time.date()
            self.bucket_start = bucket_start
            self.bucket_minutes = {}

        minute_key = (bar_time.hour, bar_time.minute)
        self.bucket_minutes[minute_key] = bar

