        start_minutes = self.bucket_start.hour * 60 + self.bucket_start.minute
        for offset in range(5):
            minute_value = start_minutes + offset
            expected.append((minute_value // 60, minute_value % 60))

        if any(key not in self.bucket_minutes for key in expected):
            self.bucket_minutes = {}
            return

        last_bar = self.bucket_minutes[expected[-1]]
        close = last_bar.Close

        self.closes.append(float(close))
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) >= self.slow_period:
            current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

            if (
                self.previous_fast is not None
                and self.previous_slow is not None
                and self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            ):
                end_minutes = start_minutes + 5
                end_time = time(end_minutes // 60, end_minutes % 60)

                if time(9, 45) <= end_time <= time(14, 30):
                    self.pending_signal = True

            self.previous_fast = current_fast
            self.previous_slow = current_slow

        self.bucket_minutes = {}

    def _enter_from_current_chain(self, slice):
        spy_bar = self._get_data(slice.Bars, self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped entry: current SPY price unavailable")
            return

        chains = getattr(slice, "OptionChains", None)
        if chains is None or len(chains) == 0:
            self.Debug("Skipped entry: no option chain")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)
        spy_price = float(spy_bar.Close)

        candidates = []

        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        expiry_candidates = [
            contract
            for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = sorted(
            expiry_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol)),
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_option_exit(self, slice):
        if self.held_option is None or self.entry_fill_price is None:
            return

        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            return

        expiry = self.held_option.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self._submit_exit("expiration-day liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        quote = self._get_data(slice.QuoteBars, self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * self.PROFIT_TARGET_MULTIPLIER:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._is_order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason,
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def _process_expiration(self):
        if self.held_option is None:
            return

        expiry = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entries_today = True
            self._submit_exit("unexpected expiration processing liquidation")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.no_entries_today = True

        if not self.spy_cleanup_submitted:
            self.spy_cleanup_submitted = True
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment cleanup",
            )
            self.Debug(
                "Unexpected exercise or assignment: liquidating {} SPY shares".format(
                    quantity
                )
            )

    def _previous_trading_day(self, date_value):
        candidate = datetime(
            date_value.year,
            date_value.month,
            date_value.day,
        ) - timedelta(days=1)

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option
                and security.Holdings.Quantity != 0
            ):
                return True
        return False

    def _has_open_entry_order(self):
        return self.entry_ticket is not None and self._is_order_open(self.entry_ticket)

    def _is_order_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def _get_data(self, data, symbol):
        if data is None:
            return None

        try:
            if data.ContainsKey(symbol):
                return data[symbol]
        except Exception:
            try:
                return data[symbol]
            except Exception:
                return None

        return None

