from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = self.option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.current_group_key = None
        self.current_group = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

        self.profit_target_percent = 0.20
        parameter = self.GetParameter("ProfitTargetPercent")
        if parameter:
            try:
                self.profit_target_percent = float(parameter)
            except Exception:
                pass

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._handle_option_expiration()
            self._handle_option_exit(slice)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_spy_minute_bar(bar, slice)

    def _process_spy_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        if not (time(9, 30) <= bar_time.time() < time(16, 0)):
            return

        group_minute = (bar_time.minute // 5) * 5
        group_key = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bar_time.hour,
            group_minute
        )

        if self.current_group_key != group_key:
            if self.current_group is not None:
                self._process_completed_five_minute_bar(
                    self.current_group_key,
                    self.current_group,
                    slice
                )

            self.current_group_key = group_key
            self.current_group = {
                "open": float(bar.Open),
                "high": float(bar.High),
                "low": float(bar.Low),
                "close": float(bar.Close),
                "volume": float(bar.Volume)
            }
            return

        self.current_group["high"] = max(
            self.current_group["high"], float(bar.High)
        )
        self.current_group["low"] = min(
            self.current_group["low"], float(bar.Low)
        )
        self.current_group["close"] = float(bar.Close)
        self.current_group["volume"] += float(bar.Volume)

    def _process_completed_five_minute_bar(self, group_key, bar, slice: Slice):
        previous_fast = None
        previous_slow = None

        if self.fast_window.IsReady:
            previous_fast = sum(self.fast_window) / self.fast_window.Count
        if self.slow_window.IsReady:
            previous_slow = sum(self.slow_window) / self.slow_window.Count

        close = bar["close"]
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not (self.fast_window.IsReady and self.slow_window.IsReady):
            return

        current_fast = sum(self.fast_window) / self.fast_window.Count
        current_slow = sum(self.slow_window) / self.slow_window.Count

        if previous_fast is None or previous_slow is None:
            return

        bar_end = group_key + timedelta(minutes=5)
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        bullish_crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_crossover:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        spy_price = float(self.Securities[self.spy_symbol].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

