from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy_security = self.AddEquity("SPY", Resolution.Minute)
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )
        self.option = option_security.Symbol

        self.fast_closes = deque(maxlen=20)
        self.slow_closes = deque(maxlen=20)

        self.bucket_start = None
        self.bucket_bars = {}

        self.current_slice = None
        self.current_spy_price = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice

        self._handle_unexpected_spy_position()
        self._process_expiration()

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            self._evaluate_exit(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        spy_bar = slice.Bars[self.spy]
        self.current_spy_price = float(spy_bar.Close)
        self._process_minute_bar(spy_bar)

    def _process_minute_bar(self, bar: TradeBar):
        bar_time = bar.Time
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._finalize_bucket()

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

    def _finalize_bucket(self):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(t in self.bucket_bars for t in expected_times):
            closes = [float(self.bucket_bars[t].Close) for t in expected_times]
            close = closes[-1]
            bar_end = self.bucket_start + timedelta(minutes=5)
            self._process_five_minute_close(bar_end, close)

        self.bucket_bars = {}

    def _process_five_minute_close(self, bar_end: datetime, close: float):
        previous_fast = None
        previous_slow = None

        if len(self.slow_closes) >= 20:
            previous_fast = sum(list(self.slow_closes)[-5:]) / 5.0
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.slow_closes) < 20:
            return

        current_fast = sum(list(self.slow_closes)[-5:]) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_crossover:
            self._attempt_entry()

    def _attempt_entry(self):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status not in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                return

        if self.current_slice is None or self.current_spy_price is None:
            self.Debug("Skipped entry: current Slice or SPY price unavailable.")
            return

        chain = self.current_slice.OptionChains.get(self.option)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * self.current_spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry={selected_expiry} strike={selected.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_symbol} price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.held_expiry = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.held_expiry is not None:
            previous_trading_day = (
                self.Securities[self.spy]
                .Exchange
                .Hours
                .GetPreviousTradingDay(self.held_expiry)
                .date()
            )

            if (
                self.Time.date() == previous_trading_day
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")
                return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0
        if midpoint >= self.entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._submit_exit("profit target")

    def _process_expiration(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
