        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.expiration_day_blocked = True

            if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
                self.entry_ticket.Cancel("Expiration processing.")

            if self.Portfolio[self.held_option].Invested:
                self.SubmitExit("expiration processing")

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating {} shares."
                .format(quantity)
            )
            self.MarketOrder(self.spy, -quantity)

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}."
                    .format(self.held_option, self.entry_fill_price)
                )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {} at {:.4f}."
                    .format(order_event.Symbol, float(order_event.FillPrice))
                )

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected exercise or assignment detected for {}."
                .format(order_event.Symbol)
            )
            self.HandleUnexpectedEquityPosition()
