        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.spy_option.Symbol
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_start = None
        self.bucket_date = None
        self.bucket_closes = []
        self.bucket_times = []

        self.held_option = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.profit_target_multiplier = 1.20
        self.expiration_blocked_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        algorithm_date = self.Time.date()

        if self.held_option is not None:
            expiry_date = self._date_of(self.held_option.ID.Date)

            if algorithm_date == expiry_date:
                self.expiration_blocked_date = algorithm_date
                if self._option_quantity() > 0:
                    self._submit_exit("Expiration-day liquidation")
            elif (
                self._option_quantity() > 0
                and self._is_pre_expiration_trading_day(algorithm_date, expiry_date)
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("Pre-expiration time stop")

            if self._option_quantity() > 0 and self.entry_price is not None:
                if slice.OptionChains.ContainsKey(self.option_symbol):
                    chain = slice.OptionChains[self.option_symbol]
                    held_contract = next(
                        (
                            contract
                            for contract in chain
                            if contract.Symbol == self.held_option
                        ),
                        None,
                    )

                    if held_contract is not None:
                        bid = float(held_contract.BidPrice)
                        ask = float(held_contract.AskPrice)

                        if bid > 0 and ask > 0:
                            midpoint = (bid + ask) / 2.0
                            if midpoint >= self.entry_price * self.profit_target_multiplier:
                                self._submit_exit("Profit target")

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            if not self.equity_liquidation_submitted:
                self.Debug(
                    f"{self.Time}: Unexpected SPY exercise or assignment; "
                    "liquidating equity position."
                )
                quantity = self.Portfolio[self.spy_symbol].Quantity
                self.MarketOrder(
                    self.spy_symbol,
                    -quantity,
                    tag="Unexpected exercise or assignment",
                )
                self.equity_liquidation_submitted = True
        else:
            self.equity_liquidation_submitted = False

        if self.entry_ticket is not None:
            if self._order_is_open(self.entry_ticket):
                return

        if self.held_option is not None or self.expiration_blocked_date == algorithm_date:
            return

        if not slice.Bars.ContainsKey(self.spy_symbol):
            return

        completed_close = self._process_minute_bar(slice.Bars[self.spy_symbol])
        if completed_close is None:
            return

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(completed_close))
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bar_end_time = self._bucket_end_time
        if not (
            time(9, 45) <= bar_end_time.time() <= time(14, 30)
        ):
            return

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover:
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"{self.Time}: Entry skipped; no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts_by_expiry = {}
        for contract in chain:
            expiry_date = self._date_of(contract.Expiry)
            if expiry_date >= minimum_expiry:
                contracts_by_expiry.setdefault(expiry_date, []).append(contract)

        if not contracts_by_expiry:
            self.Debug(f"{self.Time}: Entry skipped; no qualifying expiration.")
            return

        selected_expiry = min(contracts_by_expiry.keys())
        spy_price = float(completed_close)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts_by_expiry[selected_expiry]
            if contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no qualifying call at "
                f"{selected_expiry}."
            )
            return

        selected_contract = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol),
            ),
        )

        self.entry_ticket = self.MarketOrder(
            selected_contract.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )
        self.Debug(
            f"{self.Time}: Submitted SPY call entry for "
            f"{selected_contract.Symbol}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None
