from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import deque


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_PCT = 0.20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=20)
        self.bucket_end = None
        self.bucket_bars = []

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_cleanup_ticket = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._process_expiration_and_time_stop()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated = self._add_minute_bar(spy_bar)
        if consolidated is None:
            return

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(consolidated["close"])

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = consolidated["end"]
        eligible_time = (
            bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish_crossover and eligible_time:
            self._try_enter(slice, consolidated["close"])

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        if end_time.weekday() >= 5:
            return None

        minute = end_time.hour * 60 + end_time.minute
        if minute < 9 * 60 + 31 or minute > 16 * 60:
            self.bucket_end = None
            self.bucket_bars = []
            return None

        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if bucket_end_minute < 9 * 60 + 35 or bucket_end_minute > 16 * 60:
            return None

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = []

        if self.bucket_bars:
            expected_end = self.bucket_bars[-1]["end"] + timedelta(minutes=1)
            if end_time != expected_end:
                self.bucket_bars = []

        self.bucket_bars.append({
            "end": end_time,
            "close": float(bar.Close)
        })

        if len(self.bucket_bars) != 5 or end_time != bucket_end:
            return None

        result = {
            "end": bucket_end,
            "close": self.bucket_bars[-1]["close"]
        }
        self.bucket_bars = []
        return result

    def _try_enter(self, slice, spy_price):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_is_terminal(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped call selection: no qualifying call at selected expiration.")
            return

        contract = min(
            eligible,
            key=lambda item: (float(item.Strike), str(item.Symbol))
        )

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Submitted call entry: {}".format(contract.Symbol))

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None:
            return

        now = self.Time
        current_date = now.date()
        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if (
            current_date == previous_trading_day
            and (now.hour > 15 or (now.hour == 15 and now.minute >= 45))
        ):
            self._submit_exit("pre-expiration time stop")
            return

        quote = self.Securities[self.held_symbol].GetLastData()
        if quote is None:
            return

        current_quote = None
        if hasattr(self, "CurrentSlice") and self.CurrentSlice is not None:
            current_quote = self.CurrentSlice.QuoteBars.get(self.held_symbol)

        if current_quote is None:
            return

        bid = current_quote.Bid.Close if current_quote.Bid is not None else None
        ask = current_quote.Ask.Close if current_quote.Ask is not None else None

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target:
            self._submit_exit("profit target")

    def OnData(self, slice: Slice):
        self.CurrentSlice = slice

        self._handle_unexpected_equity_position()
        self._process_expiration_and_time_stop()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated = self._add_minute_bar(spy_bar)
        if consolidated is None:
            return

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            values = list(self.closes)
            previous_fast = sum(values[-5:]) / 5.0
            previous_slow = sum(values) / 20.0

        self.closes.append(consolidated["close"])

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        current_fast = sum(values[-5:]) / 5.0
        current_slow = sum(values) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = consolidated["end"]
        eligible_time = (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and
            (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        )

        if bullish_crossover and eligible_time:
            self._try_enter(slice, consolidated["close"])

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_is_terminal(self.exit_ticket):
            return

        if self.entry_price is None:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity
            )
            self.Debug("Submitted option exit: {}".format(reason))

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is None
            or self._ticket_is_terminal(self.equity_cleanup_ticket)
        ):
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
            self.equity_cleanup_ticket = self.MarketOrder(self.spy, -quantity)

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while True:
            candidate_dt = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
            if exchange_hours.IsDateOpen(candidate_dt):
                return candidate
            candidate -= timedelta(days=1)

    def _ticket_is_terminal(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
                self.entry_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exited option position at {:.4f}".format(
                    float(order_event.FillPrice)
                ))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

