        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated = self._add_minute_bar(spy_bar)
        if consolidated is None:
            return

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(consolidated["close"])

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = consolidated["end"]
        eligible_time = (
            bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish_crossover and eligible_time:
            self._try_enter(slice, consolidated["close"])

    def _add_minute_bar(self, bar):
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        if end_time.weekday() >= 5:
            return None

        minute = end_time.hour * 60 + end_time.minute
        if minute < 9 * 60 + 31 or minute > 16 * 60:
            self.bucket_end = None
            self.bucket_bars = []
            return None

        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end = end_time.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60,
            second=0,
            microsecond=0
        )

        if bucket_end_minute < 9 * 60 + 35 or bucket_end_minute > 16 * 60:
            return None

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = []

        if self.bucket_bars:
            expected_end = self.bucket_bars[-1]["end"] + timedelta(minutes=1)
            if end_time != expected_end:
                self.bucket_bars = []

        self.bucket_bars.append({
            "end": end_time,
            "close": float(bar.Close)
        })

        if len(self.bucket_bars) != 5 or end_time != bucket_end:
            return None

        result = {
            "end": bucket_end,
            "close": self.bucket_bars[-1]["close"]
        }
        self.bucket_bars = []
        return result

