        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_is_terminal(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped call selection: no qualifying call at selected expiration.")
            return

        contract = min(
            eligible,
            key=lambda item: (float(item.Strike), str(item.Symbol))
        )

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Submitted call entry: {}".format(contract.Symbol))

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None:
            return

        now = self.Time
        current_date = now.date()
        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if (
            current_date == previous_trading_day
            and (now.hour > 15 or (now.hour == 15 and now.minute >= 45))
        ):
            self._submit_exit("pre-expiration time stop")
            return

        quote = self.Securities[self.held_symbol].GetLastData()
        if quote is None:
            return

        current_quote = None
        if hasattr(self, "CurrentSlice") and self.CurrentSlice is not None:
            current_quote = self.CurrentSlice.QuoteBars.get(self.held_symbol)

        if current_quote is None:
            return

        bid = current_quote.Bid.Close if current_quote.Bid is not None else None
        ask = current_quote.Ask.Close if current_quote.Ask is not None else None

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target:
