from AlgorithmImports import *
from collections import deque
from datetime import datetime, date, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.current_bucket_date = None
        self.current_bucket_end = None
        self.current_minute_bars = {}

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None
        self.no_entry_date = None

        # Configurable default profit target: 20% above the filled entry price.
        self.profit_target_multiple = 1.20

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)
        self._process_expiration(current_date)
        self._process_held_option_exit(slice, current_date)

        if not slice.Bars.ContainsKey(self.spy):
            return

        minute_bar = slice.Bars[self.spy]
        completed_bar = self._add_minute_bar(minute_bar)

        if completed_bar is None:
            return

        bar_end = completed_bar.EndTime.time()
        if not (time(9, 45) <= bar_end <= time(14, 30)):
            return

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

            self.closes.append(completed_bar.Close)

            current_fast = sum(list(self.closes)[-5:]) / 5.0
            current_slow = sum(self.closes) / 20.0

            bullish_cross = (
                previous_fast <= previous_slow
                and current_fast > current_slow
            )
        else:
            self.closes.append(completed_bar.Close)
            return

        if not bullish_cross:
            return

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_order_id is not None:
            return

        self._enter_call(slice, current_date, completed_bar.Close)

    def _add_minute_bar(self, minute_bar: TradeBar):
        local_end = minute_bar.EndTime.replace(second=0, microsecond=0)
        local_date = local_end.date()
        local_time = local_end.time()

        if not (time(9, 30) < local_time <= time(16, 0)):
            return None

        minutes_from_open = int(
            (local_end - datetime.combine(local_date, time(9, 30))).total_seconds()
            // 60
        )
        bucket_end_minutes = ((minutes_from_open + 4) // 5) * 5
        bucket_end = datetime.combine(
            local_date, time(9, 30)
        ) + timedelta(minutes=bucket_end_minutes)

        if self.current_bucket_date != local_date:
            self.current_bucket_date = local_date
            self.current_bucket_end = bucket_end
            self.current_minute_bars = {}
        elif bucket_end != self.current_bucket_end:
            completed = self._complete_bucket()
            self.current_bucket_end = bucket_end
            self.current_minute_bars = {
                local_end: minute_bar
            }
            return completed

        self.current_minute_bars[local_end] = minute_bar
        return None

    def _complete_bucket(self):
        if self.current_bucket_end is None:
            return None

        expected_times = [
            self.current_bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(expected not in self.current_minute_bars for expected in expected_times):
            return None

        bars = [self.current_minute_bars[t] for t in sorted(expected_times)]
        return TradeBar(
            self.current_bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _enter_call(self, slice: Slice, current_date: date, spy_price: float):
        chain = None

        for keyed_chain in slice.OptionChains:
            if keyed_chain.Key == self.option.Symbol:
                chain = keyed_chain.Value
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.held_symbol = selected.Symbol
        self.held_expiry = selected.Expiry.date()
        self.entry_price = None

        ticket = self.MarketOrder(
            self.held_symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_order_id = ticket.OrderId

    def _process_held_option_exit(self, slice: Slice, current_date: date):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_order_id is not None:
            return

        if self.held_expiry is not None:
            preceding_day = self._preceding_trading_day(self.held_expiry)
            if (
                current_date == preceding_day
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_option_exit("Expiration time stop")
                return

        if self.entry_price is None:
            return

        held_contract = None
        for keyed_chain in slice.OptionChains:
            for contract in keyed_chain.Value:
                if contract.Symbol == self.held_symbol:
                    held_contract = contract
                    break
            if held_contract is not None:
                break

        if held_contract is None:
            return

        bid = held_contract.BidPrice
        ask = held_contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiple:
            self._submit_option_exit("Profit target")

    def _process_expiration(self, current_date: date):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if current_date >= self.held_expiry:
            self.no_entry_date = current_date
            if self.Portfolio[self.held_symbol].Invested:
                self._submit_option_exit("Expiration processing liquidation")

    def _submit_option_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_order_id is not None:
            return

        self._cancel_open_exit_order()
        ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug(
            "Exit submitted: {0} ({1})".format(self.held_symbol, reason)
        )

    def _cancel_open_exit_order(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None and ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            ticket.Cancel("Canceled by replacement exit")
        self.exit_order_id = None

    def _preceding_trading_day(self, expiry_date: date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _handle_unexpected_spy_position(self, current_date: date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.no_entry_date = current_date
        self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.entry_order_id = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.Debug("Call entry order did not fill.")
                self.entry_order_id = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call exit filled: {0}".format(order_event.Symbol))
                self.exit_order_id = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_order_id = None

