from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 1.20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast = self.SMA(5)
        self.slow = self.SMA(20)

        self._bucket_start = None
        self._bucket_bars = []
        self._bucket_valid = True
        self._last_minute = None

        self._previous_fast = None
        self._previous_slow = None
        self._pending_signal = False

        self._entry_order = None
        self._exit_order = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._update_five_minute_bar(slice)
        self._process_option_position(slice)

        if self._pending_signal:
            self._pending_signal = False
            self._try_enter(slice)

    def _update_five_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy.Symbol):
            return

        bar = slice.Bars[self.spy.Symbol]
        bar_time = bar.Time
        local_time = bar_time

        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        bucket_start = local_time.replace(
            minute=(local_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._bucket_start is None:
            self._start_bucket(bucket_start, bar)
            return

        if bucket_start != self._bucket_start:
            self._finalize_bucket()
            self._start_bucket(bucket_start, bar)
            return

        if self._last_minute is None or local_time != self._last_minute + timedelta(minutes=1):
            self._bucket_valid = False

        self._bucket_bars.append(bar)
        self._last_minute = local_time

    def _start_bucket(self, bucket_start, bar):
        self._bucket_start = bucket_start
        self._bucket_bars = [bar]
        self._bucket_valid = True
        self._last_minute = bar.Time

    def _finalize_bucket(self):
        if self._bucket_start is None:
            return

        bar_end = self._bucket_start + timedelta(minutes=5)

        if (
            self._bucket_valid
            and len(self._bucket_bars) == 5
            and self._bucket_bars[-1].Time == self._bucket_start + timedelta(minutes=4)
        ):
            close = self._bucket_bars[-1].Close

            previous_fast = self._previous_fast
            previous_slow = self._previous_slow

            self.fast.Update(bar_end, close)
            self.slow.Update(bar_end, close)

            if previous_fast is not None and previous_slow is not None:
                bullish_cross = (
                    previous_fast <= previous_slow
                    and self.fast.Current.Value > self.slow.Current.Value
                )

                end_time = bar_end.time()
                eligible_time = time(9, 45) <= end_time <= time(14, 30)

                if (
                    bullish_cross
                    and self.fast.IsReady
                    and self.slow.IsReady
                    and eligible_time
                ):
                    self._pending_signal = True

            self._previous_fast = self.fast.Current.Value
            self._previous_slow = self.slow.Current.Value

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self._blocked_entry_date == today:
            return

        if self._held_symbol is not None:
            holding = self.Portfolio[self._held_symbol]
            if holding.Invested:
                return

        if self._entry_order is not None and self._is_order_open(self._entry_order):
            return

        if not slice.Bars.ContainsKey(self.spy.Symbol):
            self.Debug("Skipped entry: no current SPY bar.")
            return

        spy_price = slice.Bars[self.spy.Symbol].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self._entry_order = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )

    def _process_option_position(self, slice: Slice):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        contract_expiry = self._held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= contract_expiry:
            self._blocked_entry_date = today
            self._submit_option_exit("expiration safety exit")
            return

        previous_trading_day = self._previous_trading_day(contract_expiry)
        now = self.Time.time()

        if today == previous_trading_day and now >= time(15, 45):
            self._submit_option_exit("pre-expiration time stop")
            return

        if self._exit_order is not None and self._is_order_open(self._exit_order):
            return

        if not slice.QuoteBars.ContainsKey(self._held_symbol):
            return

        quote = slice.QuoteBars[self._held_symbol]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self._entry_price is not None
            and midpoint >= self._entry_price * self.PROFIT_TARGET_MULTIPLE
        ):
            self._submit_option_exit("profit target")

    def _submit_option_exit(self, reason):
        if self._held_symbol is None:
            return

        if self._exit_order is not None and self._is_order_open(self._exit_order):
            self._exit_order.Cancel("Replaced by newer exit condition.")

        quantity = -self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._exit_order = self.MarketOrder(
            self._held_symbol,
            quantity,
            tag=reason
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_order is not None
            and order_event.OrderId == self._entry_order.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_order = None

        if (
            self._exit_order is not None
            and order_event.OrderId == self._exit_order.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {0} at {1}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self._exit_order = None
            self._held_symbol = None
            self._entry_price = None

        if "Exercise" in str(order_event.OrderType):
            self._handle_unexpected_exercise_or_assignment()

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.Debug("Unexpected option assignment received.")
        self._handle_unexpected_exercise_or_assignment()

    def OnExerciseOrderEvent(self, exercise_event: ExerciseOrderEvent):
        self.Debug("Unexpected option exercise received.")
        self._handle_unexpected_exercise_or_assignment()

    def _handle_unexpected_exercise_or_assignment(self):
        self._blocked_entry_date = self.Time.date()

        if self.Portfolio[self.spy.Symbol].Invested:
            quantity = -self.Portfolio[self.spy.Symbol].Quantity
            self.MarketOrder(
                self.spy.Symbol,
                quantity,
                tag="Unexpected exercise or assignment cleanup"
            )
            self.Debug("Liquidating unexpected SPY equity position.")

    def _previous_trading_day(self, date_value):
        date_time = DateTime(
            date_value.year,
            date_value.month,
            date_value.day
        )
        try:
            previous = self.spy.Exchange.Hours.GetPreviousTradingDay(date_time)
            return previous.date()
        except Exception:
            previous_date = date_value - timedelta(days=1)
            while previous_date.weekday() >= 5:
                previous_date -= timedelta(days=1)
            return previous_date

    @staticmethod
    def _is_order_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )


class Time:
    def __init__(self, hour, minute):
        self.hour = hour
        self.minute = minute

    def __ge__(self, other):
        return (self.hour, self.minute) >= (other.hour, other.minute)

    def __le__(self, other):
        return (self.hour, self.minute) <= (other.hour, other.minute)

    def __lt__(self, other):
        return (self.hour, self.minute) < (other.hour, other.minute)

    def __gt__(self, other):
        return (self.hour, self.minute) > (other.hour, other.minute)


