        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_blocked_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()
        self._process_expiration(current_date)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            self._manage_option_exit(slice)
            return

        self._store_minute_bar(spy_bar)
        self._manage_option_exit(slice)

        completed_bar = self._get_completed_five_minute_bar(spy_bar.EndTime)
        if completed_bar is None:
            return

        self._update_averages_and_trade(completed_bar, slice)

    def _store_minute_bar(self, bar):
        end_time = bar.EndTime
        self.minute_bars[end_time] = bar

        cutoff = end_time - timedelta(minutes=10)
        for timestamp in list(self.minute_bars.keys()):
            if timestamp < cutoff:
                del self.minute_bars[timestamp]

    def _get_completed_five_minute_bar(self, end_time):
        if end_time.minute % 5 != 0 or end_time.second != 0:
            return None

        expected_times = [
            end_time - timedelta(minutes=minutes)
            for minutes in range(4, -1, -1)
        ]

        bars = []
        for timestamp in expected_times:
            bar = self.minute_bars.get(timestamp)
            if bar is None or bar.EndTime.date() != end_time.date():
                return None
            bars.append(bar)

        return TradeBar(
            end_time - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _update_averages_and_trade(self, bar, slice):
        previous_fast = None
        previous_slow = None

        if len(self.fast_closes) == 5:
            previous_fast = sum(self.fast_closes) / 5.0
        if len(self.slow_closes) == 20:
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(bar.Close)
        self.slow_closes.append(bar.Close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = bar.EndTime.time()
        eligible_time = (
            time(9, 45) <= bar_end_time <= time(14, 30)
        )

        if not bullish_crossover or not eligible_time:
            return

        if self.expiration_blocked_date == self.Time.date():
            return

        if self.held_option is not None or self._entry_order_open():
            return

        self._enter_option(slice, bar.Close)

    def _enter_option(self, slice, spy_price):
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)

        candidates = []
        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiration_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiration_date >= minimum_expiration
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no eligible option expiration.")
            return

        selected_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = spy_price * 1.01
        selected = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Strike >= strike_floor
            )
        ]

        if not selected:
            self.Debug("Skipped entry: no eligible call at selected expiration.")
            return

        contract = sorted(
            selected,
            key=lambda item: (item.Strike, str(item.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )
        self.Debug(
            f"Entry submitted: {contract.Symbol}; "
            f"expiration={contract.Expiry.date()}; strike={contract.Strike}"
        )

    def _manage_option_exit(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        current_date = self.Time.date()
        expiration_date = self.held_option.ID.Date.date()

        previous_trading_day = self._previous_trading_day(expiration_date)
        time_stop = (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        )

        quote = self._get_current_option_quote(slice, self.held_option)
        target_reached = False

        if quote is not None:
            bid, ask = quote
            midpoint = (bid + ask) / 2.0
            target_reached = (
                midpoint >= self.entry_price *
                (1.0 + self.PROFIT_TARGET_PERCENT)
            )

        if target_reached:
            self._cancel_open_exit_orders()
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -self.Portfolio[self.held_option].Quantity,
                tag="SPY call profit target"
            )
            self.Debug(f"Profit-target exit submitted: {self.held_option}")
        elif time_stop:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -self.Portfolio[self.held_option].Quantity,
                tag="SPY call expiration time stop"
            )
            self.Debug(f"Expiration time-stop exit submitted: {self.held_option}")

    def _process_expiration(self, current_date):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()
        if current_date < expiration_date:
            return

        self.expiration_blocked_date = current_date

        if self._entry_order_open():
            self.entry_ticket.Cancel("Expiration processing began.")

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag="SPY expiration liquidation"
            )
            self.Debug(
                f"Unexpected expiration holding; liquidation submitted: "
                f"{self.held_option}"
            )

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected SPY exercise or assignment liquidation"
        )
        self.Debug(
            f"Unexpected SPY exercise or assignment handled; "
            f"liquidating {holding.Quantity} shares."
        )

    def _get_current_option_quote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is None:
                continue

            bid = contract.BidPrice
            ask = contract.AskPrice
            if bid > 0 and ask > 0:
                return bid, ask

        return None

    def _previous_trading_day(self, expiration_date):
        check_date = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(check_date):
            check_date -= timedelta(days=1)

        return check_date

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending
            )
        )

    def _cancel_open_exit_orders(self):
        if self.held_option is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            if order.Tag.startswith("SPY call") or order.Tag.startswith("SPY expiration"):
                self.Transactions.CancelOrder(
                    order.Id,
                    "Profit target superseded other exit order."
                )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Call entry filled: {self.held_option}; "
                    f"fill price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Option exit filled: {self.exit_ticket.Symbol}")
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if order_event.IsAssignment:
            self.Debug(
                f"Unexpected option exercise or assignment event: "
                f"{order_event.Symbol}"
            )

