        if bar is None:
            return

        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        if bar_time.date() != self.Time.date():
            return

        minute_of_day = bar_time.hour * 60 + bar_time.minute
        if minute_of_day < 9 * 60 + 30 or minute_of_day >= 16 * 60:
            return

        bucket_start = bar_time.replace(
            minute=(bar_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.minute_bucket is not None and bucket_start != self.minute_bucket:
            self._complete_bucket(self.minute_bucket, slice)

        if self.minute_bucket != bucket_start:
            self.minute_bucket = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time.minute] = bar

    def _complete_bucket(self, bucket_start: datetime, slice: Slice):
        expected_minutes = {
            (bucket_start + timedelta(minutes=i)).minute
            for i in range(5)
        }

        if set(self.bucket_bars.keys()) != expected_minutes:
            self.bucket_bars = {}
