from datetime import datetime, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_closes = []
        self.last_completed_bar_date = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._liquidate_unexpected_spy_position()
        self._process_expiration_and_time_stop()
        self._evaluate_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        now = self.Time

        if now.date() < datetime(2023, 4, 1).date():
            return

        if now.time() < datetime.strptime("09:30", "%H:%M").time():
            return

        if now.time() >= datetime.strptime("16:00", "%H:%M").time():
            self.bucket_date = None
            self.bucket_end = None
            self.bucket_closes = []
            return

        self._update_five_minute_bar(bar.Close, now, slice)

    def _update_five_minute_bar(self, close, now, slice):
        session_start = datetime.combine(now.date(), datetime.strptime(
            "09:30", "%H:%M"
        ).time())

        elapsed_minutes = int((now - session_start).total_seconds() // 60)
        bucket_number = elapsed_minutes // 5
        bucket_end = session_start + timedelta(minutes=(bucket_number + 1) * 5)

        if self.bucket_date != now.date() or self.bucket_end != bucket_end:
            self.bucket_date = now.date()
            self.bucket_end = bucket_end
            self.bucket_closes = []

        expected_index = len(self.bucket_closes)
        expected_end = bucket_end - timedelta(minutes=5 - expected_index)

        if now != expected_end:
            self.bucket_closes = []
            if now < bucket_end:
                self.bucket_closes.append(close)
            return

        self.bucket_closes.append(close)

        if len(self.bucket_closes) != 5:
            return

        completed_close = self.bucket_closes[-1]
        self.bucket_closes = []

        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast_window.Add(completed_close)
        self.slow_window.Add(completed_close)

        if self.fast_window.IsReady:
            current_fast = sum(
                self.fast_window[i] for i in range(5)
            ) / 5.0
        else:
            current_fast = None

        if self.slow_window.IsReady:
            current_slow = sum(
                self.slow_window[i] for i in range(20)
            ) / 20.0
        else:
            current_slow = None

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if current_fast is None or current_slow is None:
            return

        if prior_fast is None or prior_slow is None:
            return

        if not (
            prior_fast <= prior_slow
            and current_fast > current_slow
        ):
            return

        bar_end_time = bucket_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if not (eligible_start <= bar_end_time <= eligible_end):
            return

        self._try_enter(slice, completed_close, bucket_end)

    def _try_enter(self, slice, spy_price, bar_end):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                return
            self.entry_ticket = None
            self.entry_symbol = None

        if self.spy_option.Symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.spy_option.Symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]

        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= self.entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._submit_exit("profit target")

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None:
            return

        security = self.Securities[self.held_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= datetime.strptime(
                "15:45", "%H:%M"
            ).time()
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        self._cancel_open_exit_orders()

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )

        self.Debug(
            "Exit submitted for {}: {}".format(self.held_symbol, reason)
        )

    def _cancel_open_exit_orders(self):
        if self.held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

    def _previous_trading_day(self, date_value):
        candidate = datetime.combine(
            date_value - timedelta(days=1),
            datetime.min.time()
        )

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY position; "
                "liquidating entire equity position."
            )
            self.MarketOrder(self.spy, -quantity)
            self.no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = self.entry_symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                    self.entry_ticket = None
                    self.entry_symbol = None
                    return

                if order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_
                ):
