        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.current_bucket_end = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_requested = False
        self.expiration_block_date = None
        self.assignment_liquidation_submitted = False

        self.profit_target_pct = float(
            self.GetParameter("profit_target_pct") or "0.20"
        )

    def OnData(self, slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_existing_position(slice, current_date)

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, minute_bar, slice):
        local_end = Extensions.ConvertFromUtc(
            minute_bar.EndTime, self.TimeZone
        )

        if local_end.time() < datetime.strptime("09:31", "%H:%M").time():
            return
        if local_end.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        minute = local_end.minute
        bucket_minute = ((minute + 4) // 5) * 5
        bucket_end = local_end.replace(
            minute=0, second=0, microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end

        if bucket_end != self.current_bucket_end:
            self._finalize_bucket(self.current_bucket_end, slice)
            self.current_bucket_bars = []
            self.current_bucket_end = bucket_end

        self.current_bucket_bars.append(minute_bar)

    def _finalize_bucket(self, bucket_end, slice):
        if bucket_end.time() < datetime.strptime("09:35", "%H:%M").time():
            return

        bars = self.current_bucket_bars
        if len(bars) != 5:
            return

        bars = sorted(bars, key=lambda x: x.EndTime)

        expected_end = bucket_end - timedelta(minutes=4)
        for index, bar in enumerate(bars):
            actual_end = Extensions.ConvertFromUtc(
                bar.EndTime, self.TimeZone
            )
            expected = expected_end + timedelta(minutes=index)
            if actual_end != expected:
                return

        close = float(bars[-1].Close)

        previous_fast = None
        previous_slow = None
        if self.fast_window.IsReady:
            previous_fast = sum(self.fast_window) / 5.0
        if self.slow_window.IsReady:
            previous_slow = sum(self.slow_window) / 20.0

        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bucket_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if (
            bullish_cross
            and eligible_start <= bar_time <= eligible_end
        ):
            self._try_enter(slice, bucket_end.date(), close)

    def _try_enter(self, slice, current_date, spy_price):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chains = []
        try:
            chains = list(slice.OptionChains.Values)
        except Exception:
            pass

        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        contracts = []
        for chain in chains:
            try:
                for contract in chain.Contracts.Values:
                    contracts.append(contract)
            except Exception:
                continue

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call")
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.exit_requested = False
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _process_existing_position(self, slice, current_date):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self._liquidate_option("Expiration protection")
            return

        previous_trading_day = (
            self.Securities[self.spy.Symbol]
            .Exchange.Hours.GetPreviousTradingDay(
                datetime(expiry_date.year, expiry_date.month, expiry_date.day)
            )
            .date()
        )

        current_time = self.Time.time()
        time_stop = (
            current_date == previous_trading_day
            and current_time >= datetime.strptime("15:45", "%H:%M").time()
        )

        bid, ask = self._get_current_quote(slice, self.held_symbol)

        if bid is not None and ask is not None and bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            target = self.entry_price * (1.0 + self.profit_target_pct)
            if midpoint >= target:
                self._liquidate_option("Profit target")
                return

        if time_stop:
            self._liquidate_option("Expiration time stop")

    def _get_current_quote(self, slice, symbol):
        try:
            for chain in slice.OptionChains.Values:
                for contract in chain.Contracts.Values:
                    if contract.Symbol == symbol:
                        return float(contract.BidPrice), float(contract.AskPrice)
        except Exception:
            pass
        return None, None

    def _liquidate_option(self, reason):
        if self.held_symbol is None or self.exit_requested:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_requested = True
        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -holding.Quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            if not self.assignment_liquidation_submitted:
                self.assignment_liquidation_submitted = True
                self.Debug("Unexpected SPY exercise or assignment; liquidating")
                self.Liquidate(
                    self.spy.Symbol,
                    tag="Unexpected exercise or assignment"
                )
        else:
            self.assignment_liquidation_submitted = False

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_price)
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.exit_requested = False

        elif (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            )
        ):
            self.entry_ticket = None

    def _is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

