            pass
        return None, None

    def _liquidate_option(self, reason):
        if self.held_symbol is None or self.exit_requested:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
