from datetime import datetime, timedelta, time


class SpyLongCallCrossover(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 1.20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.closes = []
        self.current_bucket_start = None
        self.current_bucket_values = []
        self.current_bucket_last_minute = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_fill_price = None
        self.exit_ticket = None
        self.held_option = None
        self.expiration_block_date = None
        self.assignment_exit_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_option is not None:
            expiry = self.held_option.ID.Date.date()

            if current_date >= expiry:
                self.expiration_block_date = current_date
                self._submit_option_exit("expiration processing")
            elif self._is_day_before_expiration(current_date, expiry):
                if self.Time.time() >= time(15, 45):
                    self._submit_option_exit("expiration time stop")
            else:
                self._evaluate_profit_target(slice)

        spy_bar = None
        if self.spy.Symbol in slice.Bars:
            spy_bar = slice.Bars[self.spy.Symbol]

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        if bar_time.date() != self.Time.date():
            return

        minute = bar_time.time()
        if minute < time(9, 30) or minute >= time(16, 0):
            return

        bucket_minutes = (bar_time.hour * 60 + bar_time.minute - 570) // 5
        bucket_start_minutes = 570 + bucket_minutes * 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bucket_start_minutes // 60,
            bucket_start_minutes % 60
        )

        if self.current_bucket_start != bucket_start:
            self._complete_bucket(slice)

            self.current_bucket_start = bucket_start
            self.current_bucket_values = []
            self.current_bucket_last_minute = None

        if self.current_bucket_last_minute is not None:
            expected = self.current_bucket_last_minute + timedelta(minutes=1)
            if bar_time != expected:
                self.current_bucket_values = []

        self.current_bucket_values.append(bar.Close)
        self.current_bucket_last_minute = bar_time

        if len(self.current_bucket_values) == 5:
            self._complete_bucket(slice)

    def _complete_bucket(self, slice: Slice):
        if self.current_bucket_start is None:
            return

        values = self.current_bucket_values
        valid = (
            len(values) == 5
            and self.current_bucket_last_minute is not None
            and self.current_bucket_last_minute ==
                self.current_bucket_start + timedelta(minutes=4)
        )

        if valid:
            close = values[-1]

            previous_fast = None
            previous_slow = None
            if len(self.closes) >= 20:
                previous_fast = sum(self.closes[-5:]) / 5.0
                previous_slow = sum(self.closes[-20:]) / 20.0

            self.closes.append(close)

            if len(self.closes) >= 20:
                current_fast = sum(self.closes[-5:]) / 5.0
                current_slow = sum(self.closes[-20:]) / 20.0

                crossover = (
                    previous_fast is not None
                    and previous_slow is not None
                    and previous_fast <= previous_slow
                    and current_fast > current_slow
                )

                bar_end = self.current_bucket_start + timedelta(minutes=5)
                eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

                if crossover and eligible_time:
                    self._attempt_entry(slice, close)

        self.current_bucket_start = None
        self.current_bucket_values = []
        self.current_bucket_last_minute = None

    def _attempt_entry(self, slice: Slice, spy_price: float):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = None
        for canonical, candidate_chain in slice.OptionChains.items():
            if canonical == self.option.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_fill_price = None
        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="Bullish five-minute MA crossover"
        )

        self.Debug(
            f"Entry submitted: {self.entry_symbol} "
            f"expiration={selected_expiry} strike={selected.Strike}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_fill_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        bid = None
        ask = None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    bid = contract.BidPrice
                    ask = contract.AskPrice
                    break
            if bid is not None or ask is not None:
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * self.PROFIT_TARGET_MULTIPLE:
            self._cancel_exit_order()
            self._submit_option_exit("profit target")

    def _submit_option_exit(self, reason: str):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        self._cancel_exit_order()
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option} ({reason})")

    def _cancel_exit_order(self):
        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by another required market exit")
            self.exit_ticket = None

    def _is_day_before_expiration(self, current_date, expiry_date):
        check_date = expiry_date - timedelta(days=1)

        while check_date > current_date:
            if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
                datetime(check_date.year, check_date.month, check_date.day)
            ):
                return check_date == current_date

            check_date -= timedelta(days=1)

        return check_date == current_date

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        if (
            self.assignment_exit_ticket is None
            or not self._ticket_is_open(self.assignment_exit_ticket)
        ):
            self.Debug(
                f"Unexpected SPY equity position detected: {quantity}; "
                "liquidating immediately"
            )
            self.assignment_exit_ticket = self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment handling"
            )

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if (
            self.entry_ticket is not None
            and orderEvent.OrderId == self.entry_ticket.OrderId
        ):
            if orderEvent.Status == OrderStatus.Filled:
                self.entry_fill_price = orderEvent.FillPrice
                self.held_option = self.entry_symbol
                self.Debug(
                    f"Entry filled: {self.held_option} "
                    f"price={self.entry_fill_price}"
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_fill_price = None

        is_assignment = bool(
            getattr(orderEvent, "IsAssignment", False)
            or getattr(orderEvent, "IsExercise", False)
        )

        if is_assignment:
            self.Debug("Unexpected option exercise or assignment event")

            quantity = self.Portfolio[self.spy.Symbol].Quantity
            if quantity != 0:
                self.assignment_exit_ticket = self.MarketOrder(
                    self.spy.Symbol,
                    -quantity,
                    tag="Unexpected exercise or assignment handling"
                )

        if (
            self.exit_ticket is not None
            and orderEvent.OrderId == self.exit_ticket.OrderId
            and orderEvent.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {self.held_option}")
            self.held_option = None
            self.entry_fill_price = None
            self.entry_symbol = None
            self.exit_ticket = None
            self.entry_ticket = None

