        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self._submit_liquidation("expiration processing")
            return

        previous_trading_day = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            current_date == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_liquidation("pre-expiration time stop")

    def _submit_liquidation(self, reason):
        if self.held_option is None:
            return

        self._cancel_exit_order()

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0 and not self._order_is_open(self.exit_ticket):
            self.exit_ticket = self.MarketOrder(
                self.held_option, -quantity
            )
            self.Debug(
                "Exit submitted ({0}): {1}".format(reason, self.held_option)
            )

    def _get_held_contract(self, slice: Slice):
        if self.held_option is None:
            return None

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_option)
            if contract is not None:
                return contract

        return None

    def _cancel_exit_order(self):
        if self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Canceled for replacement liquidation")
        self.exit_ticket = None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        )

    def _liquidate_unexpected_spy_position(self):
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment position; liquidating.")
            self.MarketOrder(
                self.spy.Symbol,
                -self.Portfolio[self.spy.Symbol].Quantity
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: {0} at {1:.2f}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.Debug("Call entry did not fill; entry state cleared.")
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: {0}".format(self.held_option))
                self.exit_ticket = None
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

