from datetime import datetime, timedelta, time

from QuantConnect import DataNormalizationMode, Market, OptionRight, Resolution
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Orders import OrderStatus


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=True,
            leverage=1,
            extendedMarketHours=False
        )
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = []
        self.slow_values = []

        self.profit_target_multiplier = 1.20

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None
        self.current_slice = None
        self.equity_cleanup_submitted = False

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

    def OnData(self, slice):
        self.current_slice = slice
        current_date = self.Time.date()

        if self.Portfolio[self.spy].Quantity != 0:
            if not self.equity_cleanup_submitted:
                self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity
                )
                self.equity_cleanup_submitted = True
        else:
            self.equity_cleanup_submitted = False

        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiration_date = self.held_option.ID.Date.date()

        if current_date >= expiration_date:
            self.no_entry_date = current_date
            self.Debug("Expiration processing began; liquidating option.")
            self.SubmitExit("expiration")
            return

        previous_trading_day = self.PreviousTradingDay(expiration_date)
        if current_date == previous_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        quote = self.GetCurrentOptionQuote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiplier:
            self.SubmitExit("profit target")

    def OnFiveMinuteBar(self, bar):
        bar_time = bar.EndTime
        if bar_time.time() < time(9, 35):
            return

        if bar_time.time() > time(16, 0):
            return

        previous_fast = self.fast_values[-1] if len(self.fast_values) >= self.fast_period else None
        previous_slow = self.slow_values[-1] if len(self.slow_values) >= self.slow_period else None

        self.fast_values.append(float(bar.Close))
        if len(self.fast_values) > self.fast_period:
            self.fast_values.pop(0)

        self.slow_values.append(float(bar.Close))
        if len(self.slow_values) > self.slow_period:
            self.slow_values.pop(0)

        if len(self.fast_values) < self.fast_period:
            return
        if len(self.slow_values) < self.slow_period:
            return
        if previous_fast is None or previous_slow is None:
            return

        fast = sum(self.fast_values) / self.fast_period
        slow = sum(self.slow_values) / self.slow_period

        if not (time(9, 45) <= bar_time.time() <= time(14, 30)):
            return

        bullish_crossover = previous_fast <= previous_slow and fast > slow
        if not bullish_crossover:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.IsOrderClosed(self.entry_ticket):
            return

