from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    PROFIT_TARGET_PCT = 0.20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bar_date = None
        self._bar_bucket = None
        self._bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.blocked_entry_date = None
        self.time_stop_submitted = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Immediately remove any unexpected SPY equity position.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment handling: "
                "liquidating SPY equity position."
            )
            self.MarketOrder(self.spy, -spy_quantity)
            self.blocked_entry_date = today

        # Never intentionally carry an option into expiration.
        if (
            self.held_symbol is not None
            and self.expiration_date is not None
            and today >= self.expiration_date
        ):
            self.blocked_entry_date = today
            self._submit_exit("expiration processing")

        # Handle the scheduled time stop.
        if self.held_symbol is not None and self.expiration_date is not None:
            preceding_day = self._preceding_trading_day(self.expiration_date)
            if (
                today == preceding_day
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("pre-expiration time stop")

        # Evaluate the profit target using the current Slice quote.
        if self.held_symbol is not None and self.entry_fill_price is not None:
            quote = self._held_option_quote(slice)
            if quote is not None:
                bid, ask = quote
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= self.entry_fill_price * (1 + self.PROFIT_TARGET_PCT):
                        self._submit_exit("profit target")

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            local_time = end_time.astimezone(self.Time.tzinfo)
        else:
            local_time = end_time

        date = local_time.date()
        minute_of_day = local_time.hour * 60 + local_time.minute

        # Regular-session five-minute bars end at 09:35, 09:40, ..., 16:00.
        if minute_of_day < 9 * 60 + 31 or minute_of_day > 16 * 60:
            return

        bucket_end = ((minute_of_day + 4) // 5) * 5
        bucket = (date, bucket_end)
        self._bar_bucket = bucket
        self._bucket_bars.setdefault(bucket, {})[minute_of_day] = bar

        if minute_of_day != bucket_end:
            return

        bars = self._bucket_bars.pop(bucket, {})
        expected_minutes = set(range(bucket_end - 4, bucket_end + 1))

        # Missing minutes invalidate the interval; do not synthesize a bar.
        if set(bars.keys()) != expected_minutes:
            return

        close = bars[bucket_end].Close
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(local_time, close)
        self.slow.Update(local_time, close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_crossover:
            return

        if not (9 * 60 + 45 <= bucket_end <= 14 * 60 + 30):
            return

        if self.blocked_entry_date == date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if not slice.OptionChains:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        eligible_chains = []

        for chain in slice.OptionChains.Values:
            contracts = list(chain.Contracts.Values)
            if contracts:
                eligible_chains.append(contracts)

        if not eligible_chains:
            self.Debug("Skipped call selection: no contracts in current Slice.")
            return

        contracts = [
            contract
            for chain_contracts in eligible_chains
            for contract in chain_contracts
        ]

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if (contract.Expiry.date() - current_date).days >= 7
        })

        if not expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days away.")
            return

        selected_expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped call selection: no qualifying call at selected expiration."
            )
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {} expiration {} strike {:.2f}".format(
                selected.Symbol, selected_expiration, selected.Strike
            )
        )

    def _held_option_quote(self, slice: Slice):
        if self.held_symbol is None or not slice.OptionChains:
            return None

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_symbol)
            if contract is not None:
                return contract.BidPrice, contract.AskPrice

        return None

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Call exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_fill_price
                    )
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Call exit filled: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_fill_price = None
                self.expiration_date = None
                self.exit_ticket = None

        if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_ticket = None

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_ticket = None

        message = (order_event.Message or "").lower()
        if "assign" in message or "exercis" in message:
            self.Debug(
                "Unexpected exercise or assignment event: {}".format(
                    order_event.Message
                )
            )

    def _preceding_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

