        self.option.SetFilter(
            -500,
            500,
            timedelta(days=0),
            timedelta(days=730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.entry_ticket = None
        self.exit_ticket = None
        self.active_option_symbol = None
        self.entry_price = None
        self.pending_entry_signal = False
        self.pending_signal_time = None
        self.blocked_entry_dates = set()

        self.profit_target_multiplier = 1.50

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None
        previous_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        end_time = bar.EndTime.astimezone(self.TimeZone).time()
        if time(9, 45) <= end_time <= time(14, 30):
            if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
                self.pending_entry_signal = True
                self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedSpyPosition()
        self.ProcessExpirationAndTimeStop(slice)

        if not self.pending_entry_signal:
            return

        self.pending_entry_signal = False

        if current_date in self.blocked_entry_dates:
            return

        if self.active_option_symbol is not None or self.entry_ticket is not None:
            return

        if not slice.Bars.ContainsKey(self.spy.Symbol):
            self.Debug("Skipped entry: SPY price unavailable")
            return

        spy_price = slice.Bars[self.spy.Symbol].Close
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain")
            return

        selected = self.SelectContract(slice, spy_price)
        if selected is None:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def SelectContract(self, slice, spy_price):
        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiration_dates = set()

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    expiration_dates.add(expiry_date)

