        selected_expiry = min(expiration_dates)
        minimum_strike = spy_price * 1.01
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Expiry.date() != selected_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < minimum_strike:
                    continue
                candidates.append(contract)

        if not candidates:
            return None

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        return candidates[0]

    def ProcessExpirationAndTimeStop(self, slice):
        symbol = self.active_option_symbol
        if symbol is None or not self.Portfolio[symbol].Invested:
            return

        expiry_date = symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.blocked_entry_dates.add(current_date)
            self.SubmitOptionExit(symbol, "expiration")
            return

        option_security = self.Securities[symbol]
        previous_trading_day = self.PreviousTradingDay(
            option_security.Exchange.Hours,
            expiry_date
        )

        if current_date == previous_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitOptionExit(symbol, "time stop")
            return

        if not slice.QuoteBars.ContainsKey(symbol):
            return

        quote = slice.QuoteBars[symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= self.entry_price * self.profit_target_multiplier:
            self.SubmitOptionExit(symbol, "profit target")

    def SubmitOptionExit(self, symbol, reason):
        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket.Cancel("Replaced by liquidation exit")

        quantity = self.Portfolio[symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(symbol, -quantity)
        self.Debug(f"Exit submitted ({reason}): {symbol}")

    def PreviousTradingDay(self, exchange_hours, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while True:
            candidate_datetime = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )
            if exchange_hours.IsDateOpen(candidate_datetime):
                return candidate
            candidate -= timedelta(days=1)

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        self.Debug("Unexpected SPY equity position detected; liquidating")
        self.MarketOrder(self.spy.Symbol, -quantity)

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.active_option_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None
            return

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_ticket = None
                self.active_option_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

