from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self._bucket_counts = {}
        self._bucket_order = []
        self._closes = deque(maxlen=20)

        self._signal_pending = False
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None
        self._equity_exit_ticket = None

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self._held_symbol is not None:
            self.ProcessExpirationAndTimeStop(slice)
            self.ProcessProfitTarget(slice)

        if self.spy in slice.Bars:
            bucket = self.GetFiveMinuteBucket(self.Time)
            self._bucket_counts[bucket] = self._bucket_counts.get(bucket, 0) + 1
            if bucket not in self._bucket_order:
                self._bucket_order.append(bucket)

            self.consolidator.Update(slice.Bars[self.spy])

        if self._signal_pending:
            self._signal_pending = False
            self.TryEnter(slice)

    def GetFiveMinuteBucket(self, local_time):
        minute = local_time.minute - (local_time.minute % 5)
        return local_time.replace(minute=minute, second=0, microsecond=0)

    def OnFiveMinuteBar(self, sender, bar):
        if not self._bucket_order:
            return

        bucket = self._bucket_order.pop(0)
        count = self._bucket_counts.pop(bucket, 0)

        if count != 5:
            return

        if bar.End - bar.Time != timedelta(minutes=5):
            return

        if len(self._closes) == 20:
            previous = list(self._closes)
            previous_fast = sum(previous[-5:]) / 5.0
            previous_slow = sum(previous) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self._closes.append(float(bar.Close))

        if len(self._closes) < 20:
            return

        current = list(self._closes)
        current_fast = sum(current[-5:]) / 5.0
        current_slow = sum(current) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        local_end = self.Time.replace(
            hour=bar.End.hour,
            minute=bar.End.minute,
            second=bar.End.second,
            microsecond=bar.End.microsecond
        )

        eligible_time = (
            local_end.hour > 9 or
            (local_end.hour == 9 and local_end.minute >= 45)
        ) and (
            local_end.hour < 14 or
            (local_end.hour == 14 and local_end.minute <= 30)
        )

        crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if crossover and eligible_time:
            self._signal_pending = True

    def TryEnter(self, slice):
        current_date = self.Time.date()

        if self._blocked_entry_date == current_date:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self.IsOpen(self._entry_ticket.Status):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        contracts = list(chain)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def ProcessProfitTarget(self, slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_ticket is not None and self.IsOpen(self._exit_ticket.Status):
            return

        quote = self.GetCurrentOptionQuote(slice, self._held_symbol)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint >= self._entry_price * self.PROFIT_TARGET_MULTIPLE:
            self.CancelOpenExitOrder()
            quantity = self.Portfolio[self._held_symbol].Quantity
            if quantity > 0:
                self._exit_ticket = self.MarketOrder(
                    self._held_symbol,
                    -quantity,
                    tag="Profit target exit"
                )
                self.Debug("Profit-target exit submitted.")

    def ProcessExpirationAndTimeStop(self, slice):
        if self._held_symbol is None:
            return

        security = self.Securities[self._held_symbol]
        expiration_date = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiration_date:
            self._blocked_entry_date = current_date
            self.SubmitTimeStop("Expiration protection exit")
            return

        previous_trading_day = expiration_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if (
            current_date == previous_trading_day and
            self.Time.hour == 15 and
            self.Time.minute >= 45
        ):
            self.SubmitTimeStop("Pre-expiration time-stop exit")

    def SubmitTimeStop(self, tag):
        if self._exit_ticket is not None and self.IsOpen(self._exit_ticket.Status):
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity > 0:
            self._exit_ticket = self.MarketOrder(
                self._held_symbol,
                -quantity,
                tag=tag
            )
            self.Debug(tag + " submitted.")

    def GetCurrentOptionQuote(self, slice, symbol):
        if self.option_symbol not in slice.OptionChains:
            return None

        for contract in slice.OptionChains[self.option_symbol]:
            if contract.Symbol == symbol:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)
                if bid > 0 and ask > 0:
                    return bid, ask
                return None

        return None

    def CancelOpenExitOrder(self):
        if self._exit_ticket is not None and self.IsOpen(self._exit_ticket.Status):
            self._exit_ticket.Cancel("Replacing open exit order.")

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if self._equity_exit_ticket is None or not self.IsOpen(self._equity_exit_ticket.Status):
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self._equity_exit_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def IsOpen(self, status):
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event):
        if getattr(order_event, "IsAssignment", False) or getattr(order_event, "IsExercise", False):
            self.Debug("Unexpected exercise or assignment detected.")
            self.HandleUnexpectedEquityPosition()

        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = float(order_event.FillPrice)
                self._entry_ticket = None
                self.Debug(
                    "Entry filled: " + str(self._held_symbol) +
                    " at " + str(self._entry_price)
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._entry_ticket = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: " + str(order_event.Symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_ticket = None

        if (
            self._equity_exit_ticket is not None and
            order_event.OrderId == self._equity_exit_ticket.OrderId and
            order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self._equity_exit_ticket = None

