            self.ProcessProfitTarget(slice)

        if self.spy in slice.Bars:
            bucket = self.GetFiveMinuteBucket(self.Time)
            self._bucket_counts[bucket] = self._bucket_counts.get(bucket, 0) + 1
            if bucket not in self._bucket_order:
                self._bucket_order.append(bucket)

            self.consolidator.Update(slice.Bars[self.spy])

        if self._signal_pending:
            self._signal_pending = False
            self.TryEnter(slice)

    def GetFiveMinuteBucket(self, local_time):
        minute = local_time.minute - (local_time.minute % 5)
        return local_time.replace(minute=minute, second=0, microsecond=0)

    def OnFiveMinuteBar(self, sender, bar):
        if not self._bucket_order:
            return

        bucket = self._bucket_order.pop(0)
        count = self._bucket_counts.pop(bucket, 0)

        if count != 5:
            return

        if bar.End - bar.Time != timedelta(minutes=5):
            return

        if len(self._closes) == 20:
            previous = list(self._closes)
            previous_fast = sum(previous[-5:]) / 5.0
            previous_slow = sum(previous) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self._closes.append(float(bar.Close))

        if len(self._closes) < 20:
            return

        current = list(self._closes)
        current_fast = sum(current[-5:]) / 5.0
        current_slow = sum(current) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        local_end = self.Time.replace(
            hour=bar.End.hour,
            minute=bar.End.minute,
            second=bar.End.second,
            microsecond=bar.End.microsecond
        )

        eligible_time = (
            local_end.hour > 9 or
            (local_end.hour == 9 and local_end.minute >= 45)
        ) and (
            local_end.hour < 14 or
            (local_end.hour == 14 and local_end.minute <= 30)
        )

        crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if crossover and eligible_time:
            self._signal_pending = True

    def TryEnter(self, slice):
