        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_date = None

        self.profit_target_percent = float(
            self.GetParameter("ProfitTargetPercent") or 20
        )

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        self._handle_unexpected_equity_position(current_date)
        self._refresh_order_state()

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if current_date >= expiry:
                self.no_entry_date = current_date
                self.Debug(f"Expiration exit: {self.held_symbol}")
                self._submit_exit("expiration")
            elif (
                current_date == self._previous_trading_day(expiry)
                and current_time >= self._time(15, 45)
            ):
                self.Debug(f"Time-stop exit: {self.held_symbol}")
                self._submit_exit("time stop")
            else:
                self._evaluate_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self._process_minute_bar(minute_bar, slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_symbol} @ {self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {order_event.Symbol} @ {order_event.FillPrice:.4f}")
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.entry_ticket = None

        is_assignment = getattr(order_event, "IsAssignment", False)
        if is_assignment or (
            order_event.Symbol == self.spy
            and order_event.FillQuantity != 0
        ):
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.spy].Quantity != 0:
                self.Debug("Unexpected exercise or assignment; liquidating SPY.")
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Unexpected exercise or assignment"
                )

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_end = bar.End
        local_date = bar_end.date()
        local_time = bar_end.time()

        if not (
            local_time >= self._time(9, 31)
            and local_time <= self._time(16, 0)
        ):
            return

        minutes_from_first_end = (
            local_time.hour * 60
            + local_time.minute
            - (9 * 60 + 35)
        )
        bucket_number = minutes_from_first_end // 5
        bucket_end_minutes = 9 * 60 + 35 + bucket_number * 5
        bucket_end = self._minutes_to_time(bucket_end_minutes)

        if self.bucket_date != local_date or self.bucket_end != bucket_end:
            self._finalize_bucket(slice)
            self.bucket_date = local_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_time] = bar

        if len(self.bucket_bars) == 5:
            expected = {
                self._minutes_to_time(bucket_end_minutes - offset)
                for offset in range(4, -1, -1)
            }

            if set(self.bucket_bars.keys()) == expected:
                self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_date is None or self.bucket_end is None:
            return

        bucket_end_minutes = self.bucket_end.hour * 60 + self.bucket_end.minute
        expected = {
            self._minutes_to_time(bucket_end_minutes - offset)
            for offset in range(4, -1, -1)
        }

        if set(self.bucket_bars.keys()) != expected:
            self.bucket_bars = {}
            return

        closing_bar = self.bucket_bars[max(self.bucket_bars.keys())]
        close = closing_bar.Close

        prior_fast = (
            sum(list(self.closes)[-self.fast_period:])
            / self.fast_period
            if len(self.closes) >= self.fast_period
            else None
        )
        prior_slow = (
            sum(self.closes) / self.slow_period
            if len(self.closes) >= self.slow_period
            else None
        )

        self.closes.append(close)

        current_fast = (
            sum(list(self.closes)[-self.fast_period:])
            / self.fast_period
            if len(self.closes) >= self.fast_period
            else None
        )
        current_slow = (
            sum(self.closes) / self.slow_period
            if len(self.closes) >= self.slow_period
            else None
        )

        eligible_time = (
            self.bucket_end >= self._time(9, 45)
            and self.bucket_end <= self._time(14, 30)
        )

        bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and current_fast is not None
            and current_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and eligible_time
            and self.bucket_date != self.no_entry_date
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._try_enter(slice)

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_bars = {}

    def _try_enter(self, slice: Slice):
        chain = None
        try:
            chain = slice.OptionChains.get(self.option.Symbol)
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)
        current_price = self.Securities[self.spy].Price

        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        contracts = list(chain.Contracts.Values)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiry.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        contract = None
        try:
            chain = slice.OptionChains.get(self.option.Symbol)
            if chain is not None:
                contract = chain.Contracts.get(self.held_symbol)
        except Exception:
            contract = None

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        target = self.entry_price * (1 + self.profit_target_percent / 100)

        if midpoint >= target:
            self.Debug(f"Profit-target exit: {self.held_symbol}")
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._exit_order_open():
            self.exit_ticket.Cancel(f"Replacing exit: {reason}")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

    def _refresh_order_state(self):
        if self.entry_ticket is not None and not self._ticket_open(self.entry_ticket):
            if self.entry_ticket.Status != OrderStatus.Filled:
                self.entry_ticket = None

        if self.exit_ticket is not None and not self._ticket_open(self.exit_ticket):
            if self.exit_ticket.Status == OrderStatus.Filled:
                self.exit_ticket = None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._ticket_open(self.entry_ticket)
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self._ticket_open(self.exit_ticket)
        )

    def _ticket_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _handle_unexpected_equity_position(self, current_date):
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = current_date
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Unexpected exercise or assignment"
            )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _time(hour, minute):
        from datetime import time
        return time(hour, minute)

    @staticmethod
    def _minutes_to_time(total_minutes):
        from datetime import time
        return time(total_minutes // 60, total_minutes % 60)

