from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, dataNormalizationMode=DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option
        option.SetFilter(lambda u: u.IncludeWeeklys()
                         .Strikes(-500, 500)
                         .Expiration(0, 730))

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_end = None
        self.current_minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

        self.profit_target_percent = 0.50
        parameter = self.GetParameter("ProfitTargetPercent")
        if parameter:
            try:
                self.profit_target_percent = float(parameter)
            except Exception:
                pass

    def OnData(self, slice: Slice):
        current_chains = list(slice.OptionChains.Values) if slice.OptionChains else []

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()
        self.EvaluateOpenPosition(current_chains)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self.ProcessMinuteBar(bar, current_chains)

    def ProcessMinuteBar(self, bar: TradeBar, chains):
        end_time = bar.EndTime
        if end_time.date() != self.Time.date():
            return

        minute = end_time.hour * 60 + end_time.minute
        session_open = 9 * 60 + 30
        session_close = 16 * 60

        if minute <= session_open or minute > session_close:
            return

        bucket_end_minute = ((minute + 4) // 5) * 5
        bucket_end = datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            bucket_end_minute // 60,
            bucket_end_minute % 60
        )

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end

        if bucket_end != self.current_bucket_end:
            self.FinalizeFiveMinuteBar(self.current_bucket_end, chains)
            self.current_minute_bars = {}
            self.current_bucket_end = bucket_end

        self.current_minute_bars[end_time] = bar

    def FinalizeFiveMinuteBar(self, bucket_end, chains):
        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        bars = [self.current_minute_bars.get(t) for t in expected]
        if any(b is None for b in bars):
            return

        five_minute_close = bars[-1].Close
        self.fast_values.append(five_minute_close)
        self.slow_values.append(five_minute_close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(list(self.fast_values)[-5:]) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = time(9, 45) <= bucket_end.time() <= time(14, 30)
        if bullish_cross and eligible_time:
            self.TryEnterCall(chains, five_minute_close)

    def TryEnterCall(self, chains, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_chains = [
            chain for chain in chains
            if chain.Expiry.date() >= minimum_expiry
        ]

        if not eligible_chains:
            self.Debug("Skipped entry: no expiration at least seven days out")
            return

        selected_expiry = min(chain.Expiry.date() for chain in eligible_chains)
        contracts = []

        for chain in eligible_chains:
            if chain.Expiry.date() != selected_expiry:
                continue

            for contract in chain.Contracts.Values:
                symbol = contract.Symbol
                if symbol.ID.OptionRight != OptionRight.Call:
                    continue
                if symbol.ID.StrikePrice < 1.01 * spy_price:
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call at selected expiration")
            return

        selected = min(
            contracts,
            key=lambda c: (c.Symbol.ID.StrikePrice, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def EvaluateOpenPosition(self, chains):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiration = self.held_option.ID.Date.date()
        previous_trading_day = self.PreviousTradingDay(expiration)

        if self.Time.date() == previous_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitExit("time stop")
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        contract = None
        for chain in chains:
            candidate = chain.Contracts.get(self.held_option)
            if candidate is not None:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.profit_target_percent)

        if midpoint >= target:
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket):
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug("Exit submitted (" + reason + "): " + str(self.held_option))

    def HandleExpirationProcessing(self):
        if self.held_option is None:
            return

        expiration = self.held_option.ID.Date.date()
        if self.Time.date() >= expiration:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration protection")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        self.Debug("Unexpected SPY equity position; liquidating assignment/exercise position")
        self.MarketOrder(self.spy, -holding.Quantity)
        self.no_entry_date = self.Time.date()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment; liquidating SPY equity")
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.MarketOrder(self.spy, -holding.Quantity)
        self.no_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0}, price {1}".format(
                        str(self.held_option), str(self.entry_price)
                    )
                )
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Submitted
            ]:
                if order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(self.exit_ticket.Symbol))
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False
        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if isinstance(candidate, datetime) else candidate.date() if hasattr(candidate, "date") else candidate.strftime("%Y-%m-%d")

