            return

        security = slice.Bars.get(self.held_symbol)
        quote = slice.QuoteBars.get(self.held_symbol)

        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

