        if self.held_symbol is None:
            return

        expiration_date = self.held_symbol.ID.Date.date()
        preceding_day = expiration_date - timedelta(days=1)

        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            preceding_day
        ):
            preceding_day -= timedelta(days=1)

        if today == preceding_day and self.Time.time() >= time(15, 45):
            self._submit_exit("time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_is_open():
            return

        symbol = self.held_symbol
        quantity = self.Portfolio[symbol].Quantity

        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(symbol):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(symbol, -quantity)
        self.Debug("Exit submitted: " + reason)

    def _entry_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _liquidate_unexpected_equity(self, slice):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity == 0:
            return

        if (
            self.equity_cleanup_ticket is None
            or self.equity_cleanup_ticket.Status not in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            self.Debug("Unexpected SPY equity position; liquidating.")
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy.Symbol, -quantity
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment; liquidating SPY equity.")
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.equity_cleanup_ticket = self.MarketOrder(
                self.spy.Symbol, -quantity
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.target_price = (
                    self.entry_price * self.profit_target_multiple
                )
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(order_event.Symbol))
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.target_price = None

        if (
            self.equity_cleanup_ticket is not None
            and order_event.OrderId == self.equity_cleanup_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.equity_cleanup_ticket = None

