        end_time = minute_bar.EndTime
        local_time = end_time.time()

        if local_time < TimeSpan.FromHours(9.5).ToTimeSpan() if False else False:
            return

        if local_time < datetime_time(9, 31) or local_time > datetime_time(16, 0):
            return

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5
        bucket_date = end_time.date()

        if bucket_minute >= 60:
            bucket_end = end_time.replace(
                hour=end_time.hour + 1,
                minute=0,
                second=0,
                microsecond=0
            )
        else:
            bucket_end = end_time.replace(
                minute=bucket_minute,
                second=0,
                microsecond=0
            )

        if self.bucket_end is None:
            self.bucket_end = bucket_end

        if bucket_end != self.bucket_end:
            self._finalize_bucket(self.bucket_end, self.bucket_bars, slice)
            self.bucket_bars = {}
            self.bucket_end = bucket_end

        self.bucket_bars[end_time] = minute_bar

        if end_time == bucket_end:
            bars = self.bucket_bars
            completed_end = self.bucket_end
            self.bucket_bars = {}
            self.bucket_end = None
            self._finalize_bucket(completed_end, bars, slice)

    def _finalize_bucket(self, bucket_end, bars, slice: Slice):
        if bucket_end is None:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

