        consolidated = TradeBar(
            bucket_end - timedelta(minutes=5),
            self.spy,
            ordered[0].Open,
            max(b.High for b in ordered),
            min(b.Low for b in ordered),
            ordered[-1].Close,
            sum(b.Volume for b in ordered),
            timedelta(minutes=5)
        )

