            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            c.Expiry.date()
            for c in contracts
            if c.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)
        strike_floor = spy_price * 1.01

        candidates = [
            c for c in contracts
            if c.Expiry.date() == selected_expiry
            and c.Right == OptionRight.Call
            and c.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        if not self.Portfolio[self.held_option].Invested:
            return

        current_contract = None
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is not None:
            current_contract = next(
                (
                    c for c in chain.Contracts.Values
                    if c.Symbol == self.held_option
                ),
                None
            )

        bid = None
        ask = None

        if current_contract is not None:
            bid = float(current_contract.BidPrice)
            ask = float(current_contract.AskPrice)
        else:
            quote = slice.QuoteBars.get(self.held_option)
            if quote is not None:
                bid = float(quote.Bid.Close)
                ask = float(quote.Ask.Close)

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * self.PROFIT_TARGET_MULTIPLIER

        if midpoint >= target:
            self._submit_exit("profit target")

    def _process_expiration(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            if self.Portfolio[self.held_option].Invested:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Canceled before replacement exit")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -self.Portfolio[self.held_option].Quantity
        )
        self.Debug("Exit submitted: {}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0 and order_event.FillPrice > 0:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_option, self.entry_price
                    )
                )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Option exit filled at {:.4f}".format(order_event.FillPrice))
                    self.held_option = None
                    self.entry_price = None
                self.exit_ticket = None

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        current_date = self.Time.date()
        if self.last_assignment_check_date != current_date:
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating {} SPY shares.".format(
                    quantity
                )
            )
            self.last_assignment_check_date = current_date

        self.blocked_entry_date = current_date
        self.MarketOrder(self.spy, -quantity)

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]


def datetime_time(hour, minute):
    from datetime import time
    return time(hour, minute)

