from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Securities.Option import OptionRight


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy_security = self.AddEquity("SPY", Resolution.Minute)
        self.spy = self.spy_security.Symbol
        self.spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(lambda universe: universe
                              .Strikes(-200, 200)
                              .Expiration(0, 730))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.option_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        current_fast = self.fast.Current.Value if self.fast.IsReady else None
        current_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if current_fast is None or current_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        local_time = bar.EndTime
        if local_time.hour < 9 or local_time.hour > 14:
            return

        if local_time.hour == 9 and local_time.minute < 45:
            return

        if local_time.hour == 14 and local_time.minute > 30:
            return

        if (current_fast <= current_slow and
                self.fast.Current.Value > self.slow.Current.Value):
            self.pending_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.ManageOpenPosition(slice)

        if not self.pending_signal:
            return

        self.pending_signal = False

        if self.blocked_entry_date == self.Time.date():
            return

        if self.HasOpenEntryOrder() or self.HasOptionHolding():
            return

        self.SelectAndEnterOption(slice)

    def SelectAndEnterOption(self, slice):
        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration satisfies the date rule.")
            return

        selected_expiry = expiries[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
