    def OnData(self, slice):
        current_date = self.Time.date()

        self._process_expiration_and_time_stop(slice)

        if self._pending_signal_end != self.Time:
            return

        self._pending_signal_end = None

        if current_date == self._blocked_entry_date:
            return

        if self._has_option_holding() or self._entry_order_is_open():
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped selection: current SPY bar unavailable.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        contracts = []
        minimum_expiry = current_date + timedelta(days=7)

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                    and contract.Strike >= spy_price * 1.01
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_filled_quantity = 0
        self._entry_filled_value = 0.0
        self._entry_price = None
        self._held_option = selected.Symbol

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol} at strike {selected.Strike}, "
            f"expiry {selected.Expiry.date()}"
        )

    def _process_expiration_and_time_stop(self, slice):
        if self._held_option is None:
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0:
            return

        expiry_date = self._held_option.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self._blocked_entry_date = current_date
            self._submit_exit("Expiration protection", force=True)
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self._is_trading_day_immediately_before(current_date, expiry_date)
        ):
            self._submit_exit("Pre-expiration time stop", force=True)
            return

        if self._exit_order_is_open():
            return

        if self._entry_price is None:
            return

        contract = self._find_contract_in_slice(slice, self._held_option)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._submit_exit("Profit target reached")

    def _find_contract_in_slice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason, force=False):
        if self._held_option is None:
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0:
            return

        if self._exit_order_is_open():
            if not force:
                return
            self._exit_ticket.Cancel("Replacing open exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self._held_option}; reason: {reason}")

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if (
                security.Type == SecurityType.Option
                and security.Holdings.Quantity > 0
            ):
                return True
        return False

    def _entry_order_is_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        }

    def _exit_order_is_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in {
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted,
        }

    def _is_trading_day_immediately_before(self, current_date, expiry_date):
        check_date = current_date + timedelta(days=1)

        while check_date < expiry_date:
            check_datetime = datetime(
                check_date.year,
                check_date.month,
                check_date.day
            )
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(check_datetime):
                return False
            check_date += timedelta(days=1)

        return check_date == expiry_date

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self._entry_filled_quantity += order_event.FillQuantity
                self._entry_filled_value += (
                    order_event.FillQuantity * order_event.FillPrice
                )

                if self._entry_filled_quantity > 0:
                    self._entry_price = (
                        self._entry_filled_value / self._entry_filled_quantity
                    )

                self.Debug(
                    f"Entry filled: {order_event.Symbol}, "
                    f"price {order_event.FillPrice}"
                )

            if order_event.Status in {
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            } and self._entry_filled_quantity <= 0:
                self._held_option = None
                self._entry_price = None
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.FillQuantity < 0
        ):
            self.Debug(
                f"Exit filled: {order_event.Symbol}, "
                f"price {order_event.FillPrice}"
            )

            if self.Portfolio[order_event.Symbol].Quantity <= 0:
                self._held_option = None
                self._entry_price = None
                self._entry_ticket = None
                self._exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self._blocked_entry_date = self.Time.date()
        self.Debug("Unexpected option exercise or assignment processed.")

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Liquidate unexpected assignment"
            )

    def OnEndOfAlgorithm(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Liquidate residual SPY position"
            )

