from AlgorithmImports import *


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []
        self.fast = None
        self.slow = None
        self.previous_fast = None
        self.previous_slow = None

        self.current_session_date = None
        self.bucket_end = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.no_entries_today = False
        self.profit_target_percent = float(
            self.GetParameter("ProfitTargetPercent") or 50
        )

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.current_session_date != current_date:
            self.current_session_date = current_date
            self.no_entries_today = False
            self.bucket_end = None
            self.bucket_bars = []

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

        self._evaluate_option_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        bar_date = end_time.date()
        bar_time = end_time.time()

        if bar_date != self.Time.date():
            return

        if bar_time < datetime.time(9, 31) or bar_time > datetime.time(16, 0):
            return

        minute = end_time.minute
        bucket_end = end_time.replace(
            minute=(minute // 5) * 5,
            second=0,
            microsecond=0,
        )

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if minute % 5 != 0:
            return

        bars = self.bucket_bars
        completed_end = self.bucket_end
        self.bucket_end = None
        self.bucket_bars = []

        if len(bars) != 5:
            return

        close = bars[-1].Close
        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        self.previous_fast = self.fast
        self.previous_slow = self.slow
        self.fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        self.slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast > self.slow
        )

        if not bullish_cross:
            return

        if not (
            datetime.time(9, 45) <= completed_end.time() <= datetime.time(14, 30)
        ):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entries_today:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        if self.held_option is not None:
            holding = self.Portfolio[self.held_option]
            if holding.Invested or holding.Quantity != 0:
                return

        today = self.Time.date()
        minimum_expiry = today + datetime.timedelta(days=7)
        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no qualifying option chain/contracts.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= spy_price * 1.01
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol)),
        )

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested or holding.Quantity <= 0:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        target = self.entry_price * (1 + self.profit_target_percent / 100.0)

        if midpoint >= target:
            self._submit_exit("Profit target exit")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            if order.Id != (
                self.exit_ticket.OrderId if self.exit_ticket is not None else -1
            ):
                self.CancelOrder(order.Id, "Cancel competing option exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason,
        )
        self.Debug(
            "Option exit submitted: {0} ({1})".format(
                self.held_option,
                reason,
            )
        )

    def _handle_expiration_processing(self):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entries_today = True

            if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
                self.entry_ticket.Cancel("Expiration processing")

            holding = self.Portfolio[self.held_option]
            if holding.Quantity > 0:
                self._submit_exit("Expiration-day liquidation")
            return

        previous_trading_day = expiry_date - datetime.timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= datetime.timedelta(days=1)

        if (
            today == previous_trading_day
            and self.Time.time() >= datetime.time(15, 45)
        ):
            self._submit_exit("Pre-expiration time-stop")

    def _handle_unexpected_equity_position(self):
        equity_holding = self.Portfolio[self.spy]
        if equity_holding.Quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment created SPY position; liquidating."
            )
            self.MarketOrder(
                self.spy,
                -equity_holding.Quantity,
                tag="Unexpected exercise/assignment liquidation",
            )
            self.no_entries_today = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            order = self.Transactions.GetOrderById(order_event.OrderId)

            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                if order_event.FillQuantity > 0 and order_event.FillPrice > 0:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Call entry filled: {0}, price {1}".format(
                            self.held_option,
                            self.entry_price,
                        )
                    )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Call exit filled: {0}, price {1}".format(
                        self.held_option,
                        order_event.FillPrice,
                    )
                )
                self.exit_ticket = None
                self.entry_price = None
                self.held_option = None

            if order.Type in (
                OrderType.OptionExercise,
                OrderType.OptionAssignment,
            ):
                self.Debug("Unexpected option exercise or assignment detected.")
                self.no_entries_today = True
                equity_holding = self.Portfolio[self.spy]
                if equity_holding.Quantity != 0:
                    self.MarketOrder(
                        self.spy,
                        -equity_holding.Quantity,
                        tag="Unexpected exercise/assignment liquidation",
                    )

