        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 365)
        )
        self._option_symbol = option.Symbol

        self._five_minute_bars = deque(maxlen=20)
        self._current_bucket = None
        self._current_bucket_bars = {}

        self._previous_fast = None
        self._previous_slow = None

        self._entry_ticket = None
        self._entry_order_id = None

        self._held_symbol = None
        self._held_expiration = None
        self._entry_price = None
        self._exit_ticket = None

        self._no_entry_date = None
        self._equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self._held_symbol is not None:
            self._process_option_exits(slice)

        spy_bar = slice.Bars.get(self._spy)
        if spy_bar is None:
            return

        self._process_spy_minute_bar(spy_bar, slice)

    def _process_spy_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        if local_time.date() != self.Time.date():
            return

        if not (
            time(9, 30) <= local_time.time() < time(16, 0)
        ):
            return

        bucket = (
            local_time.date(),
            local_time.hour,
            (local_time.minute // 5) * 5
        )

        if self._current_bucket is not None and bucket != self._current_bucket:
            self._finalize_bucket(self._current_bucket, slice)

        if bucket != self._current_bucket:
            self._current_bucket = bucket
            self._current_bucket_bars = {}

        self._current_bucket_bars[local_time] = bar

    def _finalize_bucket(self, bucket, slice: Slice):
        bars = list(self._current_bucket_bars.values())

        # A complete five-minute bar requires all five minute bars.
        if len(bars) != 5:
            return

        bars.sort(key=lambda item: item.Time)
        expected_minutes = {
            bars[0].Time + timedelta(minutes=index)
            for index in range(5)
        }

        if {item.Time for item in bars} != expected_minutes:
            return

        consolidated = TradeBar(
            bars[0].Time,
            self._spy,
            bars[0].Open,
            max(item.High for item in bars),
            min(item.Low for item in bars),
            bars[-1].Close,
            sum(item.Volume for item in bars),
            timedelta(minutes=5)
        )

        bar_end = consolidated.EndTime
        self._five_minute_bars.append(consolidated.Close)

        if len(self._five_minute_bars) < 20:
            return

        current_fast = sum(list(self._five_minute_bars)[-5:]) / 5.0
        current_slow = sum(self._five_minute_bars) / 20.0

        bullish_cross = (
            self._previous_fast is not None and
            self._previous_slow is not None and
            self._previous_fast <= self._previous_slow and
            current_fast > current_slow
        )

        self._previous_fast = current_fast
        self._previous_slow = current_slow

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if bullish_cross:
            self._evaluate_entry(slice)

    def _evaluate_entry(self, slice: Slice):
        current_date = self.Time.date()

        if self._no_entry_date == current_date:
            return

        if self._held_symbol is not None or self._entry_order_is_open():
            return

        chain = slice.OptionChains.get(self._option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiration = current_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiration.date()
            for contract in chain
            if contract.Expiration.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        selected_expiration = expirations[0]
        spy_price = self.Securities[self._spy].Price
        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = spy_price * 1.01
        candidates = [
            contract
            for contract in chain
            if contract.Expiration.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self._entry_order_id = self._entry_ticket.OrderId

    def _process_option_exits(self, slice: Slice):
        if self._held_symbol is None:
            return

        current_date = self.Time.date()
        expiration_date = self._held_expiration

        if current_date >= expiration_date:
            self._no_entry_date = current_date
            self._submit_option_exit("Expiration-day liquidation")
            return

        prior_trading_day = self._prior_trading_day(expiration_date)
        if (
            current_date == prior_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._no_entry_date = current_date
            self._submit_option_exit("Pre-expiration time stop")
            return

        if self._exit_order_is_open():
            return

        quote = slice.QuoteBars.get(self._held_symbol)
        if quote is None:
            return

        bid = quote.Bid
        ask = quote.Ask
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if (
            self._entry_price is not None and
            midpoint >= self._entry_price * self.PROFIT_TARGET_MULTIPLE
        ):
            self._submit_option_exit("Profit target")

    def _submit_option_exit(self, reason: str):
        if self._held_symbol is None or self._exit_order_is_open():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit_order()

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} {}".format(self._held_symbol, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_order_id is not None and
            order_event.OrderId == self._entry_order_id
        ):
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.PartiallyFilled
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._held_expiration = (
                    self.Securities[order_event.Symbol].Symbol.ID.Date.date()
                )
                self.Debug(
                    "Call entry filled: {} at {}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None
                self._entry_order_id = None

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Option exit filled: {} at {}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self._held_symbol = None
                self._held_expiration = None
                self._entry_price = None
                self._exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._exit_ticket = None

        message = (order_event.Message or "").lower()
        if "assignment" in message or "exercise" in message:
            self.Debug(
                "Unexpected exercise or assignment event: {}".format(
                    order_event.Message
                )
            )
            self._liquidate_spy_position()

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected assignment handling: {}".format(
                assignment_event.Message
            )
        )
        self._liquidate_spy_position()

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self._spy].Quantity
        if quantity == 0:
            return

        if self._equity_liquidation_ticket is not None:
            return

        self.Debug(
            "Unexpected SPY equity position detected; liquidating immediately."
        )
        self._equity_liquidation_ticket = self.MarketOrder(
            self._spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self._spy].Quantity
        if quantity != 0 and self._equity_liquidation_ticket is None:
            self._equity_liquidation_ticket = self.MarketOrder(
                self._spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _prior_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self._spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def _entry_order_is_open(self):
        return self._ticket_is_open(self._entry_ticket)

    def _exit_order_is_open(self):
        return self._ticket_is_open(self._exit_ticket)

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _cancel_open_exit_order(self):
        if self._exit_order_is_open():
            self._exit_ticket.Cancel("Superseded by required liquidation")
            self._exit_ticket = None

