from AlgorithmImports import *
from collections import defaultdict
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    # Profit target is 150% of the filled option entry price.
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = {}

        self.current_chain = []
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_blocked_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Keep only the option contracts present in this exact Slice.
        self.current_chain = []
        for chain in slice.OptionChains.Values:
            self.current_chain.extend(list(chain))

        # Immediately remove any unexpected SPY equity position.
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            quantity = -self.Portfolio[self.spy.Symbol].Quantity
            self.Debug(
                "Unexpected SPY exercise or assignment detected; "
                "liquidating equity position."
            )
            self.MarketOrder(self.spy.Symbol, quantity)

        self._process_expiration_and_exits(today)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar)

    def _process_minute_bar(self, minute_bar: TradeBar):
        local_time = minute_bar.Time
        bar_date = local_time.date()
        bar_clock = local_time.time()

        if bar_clock < Time(9, 30) or bar_clock >= Time(16, 0):
            return

        minutes_from_open = (
            local_time.hour * 60 + local_time.minute
            - (9 * 60 + 30)
        )
        bucket_minute = 9 * 60 + 30 + (minutes_from_open // 5) * 5
        bucket_start = datetime(
            bar_date.year,
            bar_date.month,
            bar_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_bucket(self.bucket_start)

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[local_time] = minute_bar

        if len(self.bucket_bars) == 5:
            self._complete_bucket(bucket_start)

    def _complete_bucket(self, bucket_start):
        if not self.bucket_bars:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]
        bars = [self.bucket_bars.get(time) for time in expected_times]

        # Missing minutes mean there is no valid five-minute bar.
        if any(bar is None for bar in bars):
            self.bucket_bars = {}
            return

        consolidated_close = bars[-1].Close
        bar_end = bucket_start + timedelta(minutes=5)

        self.fast_values.append(consolidated_close)
        if len(self.fast_values) > 5:
