from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data import Slice
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Orders import OrderStatus, OrderDirection
from QuantConnect.Securities import DataNormalizationMode
from QuantConnect.Securities.Option import OptionRight


class SpyBullishCrossoverCalls(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._minute_bars = {}
        self._current_slice = None
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._no_entry_date = None
        self._equity_cleanup_submitted = False

        # Configurable 50% option-price profit target.
        self.profit_target_multiple = 1.50

    def OnData(self, slice: Slice):
        self._current_slice = slice
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing(current_date)
        self._evaluate_option_exit(slice, current_date)
        self._process_spy_minute_bar(slice)

    def _process_spy_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        end_time = bar.EndTime.replace(second=0, microsecond=0)

        if end_time.hour < 9 or (
            end_time.hour == 9 and end_time.minute < 31
        ) or end_time.hour > 16:
            return

        if end_time.hour == 16 and end_time.minute > 0:
            return

        boundary_minute = ((end_time.minute + 4) // 5) * 5
        boundary = end_time.replace(minute=0) + timedelta(minutes=boundary_minute)

        if boundary.hour == 16 and boundary.minute == 0:
            boundary = end_time.replace(hour=16, minute=0)

        bucket = self._minute_bars.setdefault(boundary, {})
        bucket[end_time] = bar

        if end_time != boundary:
            return

        expected_times = [
            boundary - timedelta(minutes=i) for i in range(1, 6)
        ]

        if any(t not in bucket for t in expected_times):
            self._minute_bars.pop(boundary, None)
            return

        bars = [bucket[t] for t in reversed(expected_times)]
        close = bars[-1].Close
        self._minute_bars.pop(boundary, None)

        self.fast.Update(boundary, close)
        self.slow.Update(boundary, close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        previous_fast = self.fast[1]
        previous_slow = self.slow[1]

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        local_time = boundary.time()
        if not (
            datetime.strptime("09:45", "%H:%M").time()
            <= local_time
            <= datetime.strptime("14:30", "%H:%M").time()
        ):
            return

        self._attempt_entry(boundary.date())

    def _attempt_entry(self, signal_date):
        if self._no_entry_date == signal_date:
            return

        if self._has_option_position() or self._entry_order_is_open():
            return

        if self._current_slice is None:
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        chains = self._current_slice.OptionChains
        if chains is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = []
        for chain in chains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                days_to_expiry = (expiry_date - signal_date).days
                if days_to_expiry < 7:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._held_symbol = selected.Symbol
        self._entry_price = None
        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY crossover call entry"
        )

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, nearest_expiry, selected.Strike
            )
        )

    def _evaluate_option_exit(self, slice: Slice, current_date):
        if not self._has_option_position():
            return

        symbol = self._held_symbol
        security = self.Securities[symbol]
        expiry_date = security.Symbol.ID.Date.date()

        if self._entry_price is None:
            return

        bid, ask = self._current_option_quote(slice, symbol)
        target_reached = (
            bid is not None
            and ask is not None
            and bid > 0
            and ask > 0
            and (bid + ask) / 2 >= self._entry_price * self.profit_target_multiple
        )

        time_stop = (
            current_date == self._previous_trading_date(expiry_date)
            and self.Time.time() >= datetime.strptime(
                "15:45", "%H:%M"
            ).time()
        )

        if target_reached:
            self._submit_option_exit("profit target")
        elif time_stop:
            self._submit_option_exit("expiration time stop")

    def _handle_expiration_processing(self, current_date):
        if not self._has_option_position():
            return

        expiry_date = self.Securities[self._held_symbol].Symbol.ID.Date.date()
        if current_date >= expiry_date:
            self._no_entry_date = current_date
            self._submit_option_exit("expiration processing")

    def _submit_option_exit(self, reason):
        if self._exit_order_is_open():
            return

        if not self._has_option_position():
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            tag="SPY option exit: " + reason
        )
        self.Debug(
            "Exit submitted: {0}, reason: {1}".format(
                self._held_symbol, reason
            )
        )

    def _current_option_quote(self, slice: Slice, symbol):
        chains = slice.OptionChains
        if chains is None:
            return None, None

        for chain in chains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract.BidPrice, contract.AskPrice

        return None, None

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self._entry_ticket = None

            elif (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if (
                self._entry_ticket is not None
                and order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._entry_ticket = None
                self._held_symbol = None
                self._entry_price = None

            if (
                self._exit_ticket is not None
                and order_event.OrderId == self._exit_ticket.OrderId
            ):
                self._exit_ticket = None

    def _handle_unexpected_equity_position(self):
        if self.spy not in self.Portfolio:
            return

        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            self._equity_cleanup_submitted = False
            return

        if not self._equity_cleanup_submitted:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected option exercise or assignment"
            )
            self._equity_cleanup_submitted = True
            self._no_entry_date = self.Time.date()

    def _has_option_position(self):
        return (
            self._held_symbol is not None
            and self._held_symbol in self.Portfolio
            and self.Portfolio[self._held_symbol].Quantity != 0
        )

    def _entry_order_is_open(self):
        return (
            self._entry_ticket is not None
            and self._entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_is_open(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _previous_trading_date(self, date):
        candidate = date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

