from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    # The requested specification does not provide a numeric target.
    PROFIT_TARGET_PCT = 0.20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_end = None
        self.bucket_bars = []

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.blocked_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()
        self._handle_option_expiration()

        if self.held_symbol is not None:
            self._evaluate_exit(slice)

        if self.held_symbol is None and self.entry_ticket is None:
            bar = slice.Bars.get(self.spy)
            if bar is not None:
                self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        if end_time.time() < time(9, 31) or end_time.time() > time(16, 0):
            return

        minute_of_day = end_time.hour * 60 + end_time.minute
        boundary = 575 + ((minute_of_day - 575) // 5) * 5
        bucket_end = datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            boundary // 60,
            boundary % 60
        )

        if self.bucket_end != bucket_end:
            if self.bucket_end is not None and len(self.bucket_bars) == 5:
                self._process_completed_five_minute_bar(
                    self.bucket_end,
                    self.bucket_bars[-1].Close,
                    slice
                )

            self.bucket_end = bucket_end
            self.bucket_bars = []

        if self.bucket_bars:
            expected = self.bucket_bars[-1].EndTime + timedelta(minutes=1)
            if end_time != expected:
                self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5 and end_time == bucket_end:
            self._process_completed_five_minute_bar(
                bucket_end,
                bar.Close,
                slice
            )
            self.bucket_bars = []

    def _process_completed_five_minute_bar(
        self,
        bar_end: datetime,
        close: float,
        slice: Slice
    ):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.blocked_date == self.Time.date():
            return

        self._enter_call(slice)

    def _enter_call(self, slice: Slice):
        if self.entry_ticket is not None or self.held_symbol is not None:
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)
        spy_price = self.Securities[self.spy].Price

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {} expiry {} strike {:.2f}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if self._is_immediately_preceding_trading_day(current_date, expiry):
            if self.Time.time() >= time(15, 45):
                self._submit_exit("expiration time stop")
                return

        quote = self._get_current_quote(slice, self.held_symbol)
        if quote is None or self.entry_price is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target:
            self._submit_exit("profit target")

    def _get_current_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    return bid, ask
        return None

    def _submit_exit(self, reason: str):
        if self.exit_ticket is not None or self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Call exit submitted: {}".format(reason))

    def _handle_option_expiration(self):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self._submit_exit("expiration processing")
            self.blocked_date = self.Time.date()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
        self.MarketOrder(self.spy, -quantity)
        self.blocked_date = self.Time.date()

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        next_date = current_date + timedelta(days=1)

        while next_date < expiry_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(next_date.year, next_date.month, next_date.day)
            ):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_symbol = orderEvent.Symbol
                self.entry_price = orderEvent.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug("Call exit filled: {}".format(orderEvent.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

        if hasattr(orderEvent, "IsAssignment") and orderEvent.IsAssignment:
            self.Debug("Unexpected option exercise or assignment detected.")
            self.blocked_date = self.Time.date()

