        target = self.entry_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target:
            self._submit_exit("profit target")

    def _get_current_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    return bid, ask
        return None

    def _submit_exit(self, reason: str):
        if self.exit_ticket is not None or self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Call exit submitted: {}".format(reason))

    def _handle_option_expiration(self):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self._submit_exit("expiration processing")
            self.blocked_date = self.Time.date()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
        self.MarketOrder(self.spy, -quantity)
        self.blocked_date = self.Time.date()

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        next_date = current_date + timedelta(days=1)

        while next_date < expiry_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(next_date.year, next_date.month, next_date.day)
            ):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_symbol = orderEvent.Symbol
                self.entry_price = orderEvent.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug("Call exit filled: {}".format(orderEvent.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

        if hasattr(orderEvent, "IsAssignment") and orderEvent.IsAssignment:
            self.Debug("Unexpected option exercise or assignment detected.")
            self.blocked_date = self.Time.date()

