        if self.signal_pending:
            self.signal_pending = False
            self._evaluate_entry(slice, current_date)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        if bullish:
            bar_time = bar.EndTime.time()
            if time(9, 45) <= bar_time <= time(14, 30):
                self.signal_pending = True
                self.signal_date = bar.EndTime.date()
                self.signal_time = bar.EndTime

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def _evaluate_entry(self, slice: Slice, current_date):
        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._is_terminal(self.entry_ticket.Status):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        current_price = float(slice.Bars[self.spy].Close)
        minimum_strike = current_price * 1.01
