                expiry_date = contract.Expiry.date()
                if (
                    expiry_date >= minimum_expiry and
                    contract.Right == OptionRight.Call and
                    float(contract.Strike) >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}.".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_held_position(self, slice: Slice, current_date):
        if self.held_symbol is None:
            return

        if self.held_symbol not in self.Portfolio:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self._is_terminal(self.exit_ticket.Status):
            return

        quote = slice.QuoteBars[self.held_symbol] if self.held_symbol in slice.QuoteBars else None

        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid > 0 and ask > 0 and self.entry_price is not None:
                midpoint = (bid + ask) / 2.0
