                    self._cancel_open_exit_order()
                    self.exit_ticket = self.MarketOrder(
                        self.held_symbol,
                        -quantity
                    )
                    self.Debug(
                        "Profit exit submitted: {0}, midpoint {1:.2f}.".format(
                            self.held_symbol, midpoint
                        )
                    )
                    return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
            self.Debug("Expiration time-stop submitted: {0}.".format(self.held_symbol))

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date < expiry_date:
            return

        self.blocked_entry_date = current_date
        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity > 0:
            self._cancel_open_exit_order()
            self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
            self.Debug(
                "Unexpected position at expiration; liquidation submitted: {0}.".format(
                    self.held_symbol
                )
            )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is None or
            self._is_terminal(self.equity_liquidation_ticket.Status)
        ):
            self.Debug(
                "Unexpected SPY equity position, likely exercise or assignment; "
                "liquidation submitted."
            )
            self.equity_liquidation_ticket = self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if order_event.FillPrice > 0:
                    self.entry_price = float(order_event.FillPrice)

                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = self.entry_ticket.Symbol
                    self.entry_ticket = None
                    self.Debug(
                        "Entry filled: {0} at {1:.2f}.".format(
                            self.held_symbol, self.entry_price
                        )
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}.".format(self.held_symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None and
            order_event.OrderId == self.equity_liquidation_ticket.OrderId and
            order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.equity_liquidation_ticket = None

    def _cancel_open_exit_order(self):
        if (
            self.exit_ticket is not None and
            not self._is_terminal(self.exit_ticket.Status)
        ):
            self.exit_ticket.Cancel("Replacing with immediate liquidation order.")

    def _is_terminal(self, status):
        return status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = datetime.combine(date_value, time.min) - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

