from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None

        parameter = self.GetParameter("ProfitTargetPct")
        self.profit_target_pct = float(parameter) if parameter else 0.50

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position(today)
        self._process_expiration(today)
        self._evaluate_held_position(slice, today)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is None:
            return

        local_time = self.Time

        if local_time.time() < datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time.time() >= datetime.strptime("16:00", "%H:%M").time():
            return

        bucket = self._get_bucket_start(local_time)
        if self.bucket_start is not None and bucket != self.bucket_start:
            self._finalize_bucket(slice)

        if self.bucket_start != bucket:
            self.bucket_start = bucket
            self.bucket_bars = {}

        minute_start = local_time.replace(second=0, microsecond=0)
        self.bucket_bars[minute_start] = bar

    def _get_bucket_start(self, local_time: datetime) -> datetime:
        session_start = local_time.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        minutes = int((local_time - session_start).total_seconds() // 60)
        offset = (minutes // 5) * 5
        return session_start + timedelta(minutes=offset)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if len(self.bucket_bars) != 5:
            self.bucket_bars = {}
            return

        if any(timestamp not in self.bucket_bars for timestamp in expected):
            self.bucket_bars = {}
            return

        closes = [self.bucket_bars[timestamp].Close for timestamp in expected]
        close = closes[-1]
        end_time = self.bucket_start + timedelta(minutes=5)

        self._process_consolidated_bar(end_time, close, slice)
        self.bucket_bars = {}

    def _process_consolidated_bar(
        self,
        end_time: datetime,
        close: float,
        slice: Slice
    ):
        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.slow_window) < 20:
            return

        current_fast = sum(self.fast_window) / len(self.fast_window)
        current_slow = sum(self.slow_window) / len(self.slow_window)

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_time.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        ):
            return

        self._try_enter(slice, close, end_time.date())

    def _try_enter(self, slice: Slice, spy_price: float, current_date):
        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish five-minute crossover entry"
        )

    def _evaluate_held_position(self, slice: Slice, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if self._is_immediately_preceding_trading_day(
            current_date, expiry_date
        ) and self.Time.time() >= datetime.strptime(
            "15:45", "%H:%M"
        ).time():
            self._submit_exit("SPY call day-before-expiration exit")
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.profit_target_pct)

        if midpoint >= target:
            self._submit_exit("SPY call profit-target exit")

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if current_date >= expiry_date:
            self.no_entry_date = current_date

            if self.entry_ticket is not None and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self.entry_ticket.Cancel("Expiration processing began")

            self._submit_exit("SPY call expiration protection")

    def _submit_exit(self, tag: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=tag
        )

    def _handle_unexpected_equity_position(self, current_date):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity == 0:
            return

        self.no_entry_date = current_date
        self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
        self.MarketOrder(
            self.spy_symbol,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _is_immediately_preceding_trading_day(
        self,
        current_date,
        expiry_date
    ) -> bool:
        if current_date >= expiry_date:
            return False

        candidate = expiry_date - timedelta(days=1)

        while candidate >= current_date:
            if self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
                candidate
            ):
                return candidate == current_date
            candidate -= timedelta(days=1)

        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and (
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entered {self.held_symbol} at filled price "
                    f"{self.entry_price:.2f}."
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order was canceled or invalid.")
                self.entry_ticket = None
                self.held_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and (
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exited {self.held_symbol}.")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

