        self.Debug("Exit submitted: {}".format(reason))

    def _get_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

