        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry = self.held_symbol.ID.Date.date()
        previous_trading_day = self.PreviousTradingDay(expiry)

        if (
            today == previous_trading_day and
            (self.Time.hour > 15 or (self.Time.hour == 15 and self.Time.minute >= 45))
        ):
            if not any(self.IsOpen(ticket) for ticket in self.exit_tickets):
                self.CancelOpenExitOrders()
                ticket = self.MarketOrder(self.held_symbol, -quantity)
                self.exit_tickets.append(ticket)
                self.Debug(f"Time-stop exit submitted: {self.held_symbol}")

    def HandleExpirationProcessing(self, today):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if today >= expiry:
            self.block_entries_date = today
            quantity = self.Portfolio[self.held_symbol].Quantity

            if quantity > 0 and not any(self.IsOpen(ticket) for ticket in self.exit_tickets):
                self.CancelOpenExitOrders()
                ticket = self.MarketOrder(self.held_symbol, -quantity)
                self.exit_tickets.append(ticket)
                self.Debug(
                    f"Unexpected expiration exposure; liquidation submitted: "
                    f"{self.held_symbol}"
                )

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self.equity_liquidation_submitted:
            self.Debug(
                f"Unexpected SPY exercise or assignment position detected: "
                f"quantity={quantity}"
            )
            self.MarketOrder(self.spy, -quantity)
            self.equity_liquidation_submitted = True

    def PreviousTradingDay(self, date_value):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date_value - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def CancelOpenExitOrders(self):
        for ticket in self.exit_tickets:
            if self.IsOpen(ticket):
                ticket.Cancel("Replacing open exit order")

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_fill_price:.4f}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        for ticket in self.exit_tickets:
            if ticket is not None and order_event.OrderId == ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice:.4f}"
                    )
                    if self.Portfolio[order_event.Symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_fill_price = None

                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_tickets = [
                        open_ticket for open_ticket in self.exit_tickets
                        if open_ticket.OrderId != ticket.OrderId
                    ]

