from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option = option

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.pending_signal_time = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

        self.profit_target_pct = 0.20

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if bar_time < time(9, 30) or bar_time > time(16, 0):
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and bar_time >= time(9, 45)
            and bar_time <= time(14, 30)
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        now = self.Time
        today = now.date()

        self.HandleUnexpectedSpyPosition()

        if self.held_symbol is not None:
            expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry_date:
                self.blocked_entry_date = today
                self.SubmitExit("expiration processing")
            elif (
                now.time() >= time(15, 45)
                and today == self.PreviousTradingDay(expiry_date)
            ):
                self.SubmitExit("expiration time stop")
            else:
                self.CheckProfitTarget(slice)

        if (
            self.pending_signal_time is not None
            and self.pending_signal_time.date() == today
            and self.pending_signal_time.time() >= time(9, 45)
            and self.pending_signal_time.time() <= time(14, 30)
        ):
            self.pending_signal_time = None
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self.IsOrderOpen(self.entry_ticket):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped call selection: no current SPY price.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain.Contracts.Values
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiries:
            self.Debug("Skipped call selection: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

