from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extended_market_hours=False,
            fill_forward=False,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(-100, 100, 0, 730)
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.bucket_end = None
        self.bucket_closes = {}

        self.held_contract = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_date = None

        # Configurable default profit target: 20% above the filled entry price.
        try:
            self.profit_target_multiplier = 1.0 + float(
                self.GetParameter("profit-target-percent") or 20
            ) / 100.0
        except Exception:
            self.profit_target_multiplier = 1.20

    def _is_open_order(self, ticket):
        if ticket is None:
            return False
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        )

    def _contract_expiry(self, symbol):
        return symbol.ID.Date.date()

    def _is_previous_trading_day(self, expiry_date, current_date):
        candidate = expiry_date - timedelta(days=1)
        while candidate >= current_date - timedelta(days=10):
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(candidate.year, candidate.month, candidate.day)
            ):
                return candidate == current_date
            candidate -= timedelta(days=1)
        return False

    def _finalize_bucket(self):
        if self.bucket_end is None:
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        if all(t in self.bucket_closes for t in expected):
            close = self.bucket_closes[self.bucket_end]
            self.closes.append(close)

            if len(self.closes) > self.slow_period:
                self.closes = self.closes[-self.slow_period:]

            if len(self.closes) >= self.slow_period:
                preceding = self.closes[:-1]
                previous_fast = sum(preceding[-self.fast_period:]) / self.fast_period
                previous_slow = sum(preceding[-self.slow_period:]) / self.slow_period
                current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
                current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

                crossover = (
                    previous_fast <= previous_slow and
                    current_fast > current_slow
                )

                end_time = self.bucket_end.time()
                eligible = time(9, 45) <= end_time <= time(14, 30)

                if crossover and eligible:
                    self._try_enter()

    def _try_enter(self):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_contract is not None:
            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity != 0:
                return

        if self._is_open_order(self.entry_ticket) or self._is_open_order(self.exit_ticket):
            return

        if self.spy not in self.Securities:
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        if self.option_symbol not in self.CurrentSlice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        chain = self.CurrentSlice.OptionChains[self.option_symbol]
        contracts = list(chain.Contracts.Values)

        minimum_expiry = today + timedelta(days=7)
        eligible_expiries = [
            self._contract_expiry(contract.Symbol)
            for contract in contracts
            if self._contract_expiry(contract.Symbol) >= minimum_expiry
        ]

        if not eligible_expiries:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = min(eligible_expiries)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if self._contract_expiry(contract.Symbol) == selected_expiry
            and contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiring {}".format(
                selected.Symbol, selected_expiry
            )
        )

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self._is_open_order(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_contract, reason))

    def _evaluate_exit(self, slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        expiry_date = self._contract_expiry(self.held_contract)

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            self._submit_exit("Expiration protection")
            return

        if (
            self.Time.time() >= time(15, 45) and
            self._is_previous_trading_day(expiry_date, self.Time.date())
        ):
            self.no_entry_date = self.Time.date()
            self._submit_exit("Pre-expiration time stop")
            return

        if self._is_open_order(self.exit_ticket):
            return

        if self.held_contract not in slice.OptionChains:
            return

        chain = slice.OptionChains[self.held_contract]
        contract = None

        for candidate in chain.Contracts.Values:
            if candidate.Symbol == self.held_contract:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiplier:
            self._submit_exit("Profit target")

    def OnData(self, slice):
        today = self.Time.date()

        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = today
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity.")
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Unexpected exercise or assignment"
            )

        self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_time = self.Time.replace(second=0, microsecond=0)

        if not (
            time(9, 30) <= local_time.time() <= time(16, 0)
        ):
            return

        minute = local_time.minute
        bucket_end_minute = ((minute - 30) // 5 + 1) * 5
        bucket_end = local_time.replace(minute=0) + timedelta(
            minutes=bucket_end_minute
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finalize_bucket()
            self.bucket_closes = {}

        self.bucket_end = bucket_end
        self.bucket_closes[local_time] = bar.Close

        if local_time == bucket_end:
            self._finalize_bucket()
            self.bucket_closes = {}

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None and
                order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} at {:.2f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )

            elif (
                self.exit_ticket is not None and
                order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {} at {:.2f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment detected.")

