            self.Debug("Unexpected SPY exercise/assignment; liquidating equity.")
            self.MarketOrder(
                self.spy_symbol,
                -equity_holding.Quantity,
                tag="Unexpected exercise or assignment cleanup"
            )
            self.equity_cleanup_pending = True

        if equity_holding.Quantity == 0:
            self.equity_cleanup_pending = False

        # Expiration processing takes precedence over all other strategy actions.
        if self.held_symbol is not None:
            expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry:
                self.expiration_block_date = today
                self._submit_exit("Expiration processing")
            elif (
                today == self._previous_trading_day(expiry)
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("Expiration-eve time stop")

        # Evaluate the profit target on every minute Slice.
        self._evaluate_profit_target(slice)

        # Process the current SPY minute bar for five-minute consolidation.
        if slice.Bars.ContainsKey(self.spy_symbol):
            self._process_minute_bar(slice.Bars[self.spy_symbol], slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if local_time.hour < 9 or (
            local_time.hour == 9 and local_time.minute < 30
        ) or local_time.hour >= 16:
            return

        minutes_from_open = (local_time.hour - 9) * 60 + local_time.minute - 30
        bucket_index = minutes_from_open // 5
        key = (local_time.date(), bucket_index)

        if self.bucket_key is None:
            self.bucket_key = key
        elif key != self.bucket_key:
            self._finalize_bucket(slice)
            self.bucket_key = key
            self.bucket_bars = []

        self.bucket_bars.append(bar)

    def _finalize_bucket(self, slice: Slice):
        # A complete five-minute bar requires all five minute bars.
        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        bars = self.bucket_bars
        close = bars[-1].Close
        bar_end = bars[-1].EndTime
        if bar_end.tzinfo is not None:
            bar_end = bar_end.replace(tzinfo=None)

        previous_fast = None
        previous_slow = None
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(float(close))

        if len(self.closes) < 20:
            self.bucket_bars = []
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        )

        if bullish_cross and eligible_time:
            self._try_entry(slice, float(close), bar_end.date())

        self.bucket_bars = []

