        if self.expiration_block_date == algorithm_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(self.entry_ticket):
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)
        candidates = []

