        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe.Strikes(-100, 100)
                         .Expiration(0, 365))
        self.option = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.held_option = None

        target_parameter = self.GetParameter("ProfitTargetPercent")
        try:
            self.profit_target_fraction = float(target_parameter or "20") / 100.0
        except ValueError:
            self.profit_target_fraction = 0.20

        self.no_entry_date = None

    def OnData(self, slice: Slice):
        local_date = self.Time.date()

        self._handle_unexpected_spy_position(local_date)
        self._handle_expiration_processing(local_date)
        self._evaluate_minute_exit(slice, local_date)

        if self.no_entry_date == local_date:
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        completed_close = self._update_five_minute_bar(spy_bar)
        if completed_close is None:
            return

        bar_end = self._bar_end_time(spy_bar)
        if not (bar_end.hour == 9 and bar_end.minute >= 45) and not (
            10 <= bar_end.hour <= 13
        ) and not (bar_end.hour == 14 and bar_end.minute <= 30):
            return

        self._try_enter(slice, completed_close, local_date)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_option = self.entry_ticket.Symbol
                self.Debug(
                    f"ENTRY FILLED {self.held_option} "
                    f"price={self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled,
            ) and order_event.Status != OrderStatus.PartiallyFilled:
                self.Debug(f"ENTRY ORDER CLOSED status={order_event.Status}")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"EXIT FILLED {self.exit_ticket.Symbol}")
                self.exit_ticket = None
                self.entry_price = None
                self.held_option = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

    def _update_five_minute_bar(self, minute_bar):
        bar_time = minute_bar.Time
        if hasattr(bar_time, "tzinfo") and bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        if not (9 <= bar_time.hour <= 15):
            return None
        if bar_time.hour == 9 and bar_time.minute < 30:
            return None
        if bar_time.hour == 15 and bar_time.minute >= 55:
            return None

        minutes_from_open = (bar_time.hour * 60 + bar_time.minute) - (9 * 60 + 30)
        bucket_start_minute = (minutes_from_open // 5) * 5
        bucket_start = bar_time.replace(
            hour=9,
            minute=30,
            second=0,
            microsecond=0,
        ) + timedelta(minutes=bucket_start_minute)

        if self.current_bucket is not None and bucket_start.date() != self.current_bucket.date():
            self.current_bucket = None
            self.bucket_bars = {}

        if self.current_bucket is None:
            self.current_bucket = bucket_start
            self.bucket_bars = {}
        elif bucket_start != self.current_bucket:
            completed = self._complete_bucket()
            self.current_bucket = bucket_start
            self.bucket_bars = {}
            self.bucket_bars[bar_time] = minute_bar
            return completed

        self.bucket_bars[bar_time] = minute_bar

        if len(self.bucket_bars) == 5:
            return self._complete_bucket()

        return None

    def _complete_bucket(self):
        if self.current_bucket is None or len(self.bucket_bars) != 5:
            return None

        expected_times = [
            self.current_bucket + timedelta(minutes=i) for i in range(5)
        ]
        if any(expected_time not in self.bucket_bars for expected_time in expected_times):
            return None

        close = self.bucket_bars[expected_times[-1]].Close
        self.closes.append(float(close))

        if len(self.closes) < self.slow_period:
            self.previous_fast = None
            self.previous_slow = None
            return close

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_cross:
            return close

        return close

    def _try_enter(self, slice, spy_price, local_date):
        if self._option_holding_exists():
            return
        if self._order_is_open(self.entry_ticket):
            return
        if self._order_is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            self.Debug("ENTRY SKIPPED: no option chain")
            return

        minimum_expiry = local_date + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.values()
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("ENTRY SKIPPED: no expiration at least 7 days away")
            return

        selected_expiry = expirations[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract
            for contract in chain.Contracts.values()
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("ENTRY SKIPPED: no qualifying call contract")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )

        self.Debug(
            f"ENTRY SUBMITTED {selected.Symbol} "
            f"expiry={selected_expiry} strike={selected.Strike:.2f}"
        )

    def _evaluate_minute_exit(self, slice, local_date):
        if self.held_option is None or not self._option_holding_exists():
            return
        if self.entry_price is None:
            return
        if self._order_is_open(self.exit_ticket):
            return

        contract = self._find_contract(slice, self.held_option)
        current_price = None

        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)
            if bid > 0 and ask > 0:
                current_price = (bid + ask) / 2.0

        time = self.Time
        expiry_date = self.held_option.ID.Date.date()
        previous_trading_date = self._previous_trading_day(expiry_date)

        target_reached = (
            current_price is not None
            and current_price >= self.entry_price * (1.0 + self.profit_target_fraction)
        )

        time_stop = (
            local_date == previous_trading_date
            and (time.hour > 15 or (time.hour == 15 and time.minute >= 45))
        )

        if target_reached or time_stop:
            reason = "profit target" if target_reached else "expiration time stop"
            self._submit_exit(reason)

    def _handle_expiration_processing(self, local_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if local_date >= expiry_date:
            self.no_entry_date = local_date
            if self._option_holding_exists() and not self._order_is_open(self.exit_ticket):
                self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self, local_date):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.no_entry_date = local_date
            self.Debug(
                f"UNEXPECTED SPY POSITION quantity={holding.Quantity}; liquidating"
            )
            if not self._order_is_open(self.exit_ticket):
                self.MarketOrder(
                    self.spy,
                    -holding.Quantity,
                    tag="Unexpected exercise or assignment liquidation",
                )

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=f"Option exit: {reason}",
        )
        self.Debug(f"EXIT SUBMITTED {self.held_option}: {reason}")

    def _find_contract(self, slice, symbol):
        chain = slice.OptionChains.get(self.option)
        if chain is None:
            return None
        return chain.Contracts.get(symbol)

    def _option_holding_exists(self):
        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return True

        for security_holding in self.Portfolio.Values:
            if (
                security_holding.Invested
                and security_holding.Symbol.SecurityType == SecurityType.Option
            ):
                self.held_option = security_holding.Symbol
                return True

        return False

    def _order_is_open(self, ticket):
        if ticket is None:
            return False
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate

    def _bar_end_time(self, bar):
        end_time = bar.EndTime
        if hasattr(end_time, "tzinfo") and end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)
        return end_time

