from datetime import timedelta, time


class SpyLongCallCrossover(QCAlgorithm):
    PROFIT_TARGET_MULTIPLIER = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_canonical = option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self._bucket_date = None
        self._bucket_start_minute = None
        self._bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry:
                self.blocked_entry_date = today
                if holding.Quantity != 0:
                    self._submit_exit("expiration processing")
            else:
                self._evaluate_held_position(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute(spy_bar, slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        minute = local_time.hour * 60 + local_time.minute
        if local_time.date() != self.Time.date():
            return
        if minute < session_start or minute >= session_end:
            return

        bucket_start = session_start + ((minute - session_start) // 5) * 5

        if (
            self._bucket_date != local_time.date()
            or self._bucket_start_minute != bucket_start
        ):
            self._finalize_bucket(slice)

            self._bucket_date = local_time.date()
            self._bucket_start_minute = bucket_start
            self._bucket_bars = {}

        self._bucket_bars[minute] = bar

    def _finalize_bucket(self, slice: Slice):
        if self._bucket_date is None:
            return

        expected = set(range(
            self._bucket_start_minute,
            self._bucket_start_minute + 5
        ))

        if set(self._bucket_bars.keys()) != expected:
            self._bucket_bars = {}
            return

        closes = [
            self._bucket_bars[minute].Close
            for minute in sorted(self._bucket_bars)
        ]

        close = closes[-1]
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not (self.fast_window.IsReady and self.slow_window.IsReady):
            self._bucket_bars = {}
            return

        current_fast = sum(
            self.fast_window[i] for i in range(self.fast_window.Count)
        ) / self.fast_window.Count
        current_slow = sum(
            self.slow_window[i] for i in range(self.slow_window.Count)
        ) / self.slow_window.Count

        previous_fast = None
        previous_slow = None

        if self.fast_window.Count >= 2 and self.slow_window.Count >= 2:
            previous_fast = sum(
                self.fast_window[i]
                for i in range(1, self.fast_window.Count)
            ) / (self.fast_window.Count - 1)
            previous_slow = sum(
                self.slow_window[i]
                for i in range(1, self.slow_window.Count)
            ) / (self.slow_window.Count - 1)

        bucket_end_minute = self._bucket_start_minute + 5
        end_hour = bucket_end_minute // 60
        end_minute = bucket_end_minute % 60
        bar_end_time = time(end_hour, end_minute)

        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)
        bullish = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish and eligible_time:
            self._try_enter(slice, close)

        self._bucket_bars = {}

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_symbol is not None:
            if self.Portfolio[self.held_symbol].Quantity != 0:
                return

        if self._entry_order_is_open():
            return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped selection: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no expiration at least 7 days away.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        strike_floor = spy_price * 1.01

        strikes = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= strike_floor
        ]

        if not strikes:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        selected = sorted(
            strikes,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiration {nearest_expiry}; strike {selected.Strike}"
        )

    def _evaluate_held_position(self, slice: Slice):
        if self.held_symbol is None or self.entry_fill_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity == 0:
            return

        if self._exit_order_is_open():
            return

        contract = None
        for chain in slice.OptionChains:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is not None:
            bid = contract.BidPrice
            ask = contract.AskPrice

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_fill_price * self.PROFIT_TARGET_MULTIPLIER:
                    self._submit_exit("profit target")
                    return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_trading_day = expiry - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol}; reason: {reason}")

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"liquidating {holding.Quantity} SPY shares."
            )
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.blocked_entry_date = self.Time.date()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"Unexpected assignment handling: {assignment_event.Symbol}"
        )
        self.blocked_entry_date = self.Time.date()

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Assignment liquidation"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.PartiallyFilled,
                    OrderStatus.Filled
                ):
                    if order_event.FillQuantity > 0:
                        self.held_symbol = order_event.Symbol
                        self.entry_fill_price = order_event.FillPrice
                        self.Debug(
                            f"Entry filled: {order_event.Symbol}; "
                            f"price {order_event.FillPrice}"
                        )

                if order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol}; "
                        f"price {order_event.FillPrice}"
                    )
                    if self.Portfolio[order_event.Symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_fill_price = None
                        self.exit_ticket = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

