        if self.spy not in data.Bars:
            return

        spy_bar = data.Bars[self.spy]
        completed_bar = self._update_five_minute_bar(spy_bar)

        if completed_bar is None:
            return

        self._evaluate_crossover_entry(data, completed_bar)

    def _update_five_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        total_minutes = end_time.hour * 60 + end_time.minute
        bucket_end = ((total_minutes - 1) // 5 + 1) * 5
        bucket_key = (end_time.date(), bucket_end)

        if self._bucket_key is not None and bucket_key != self._bucket_key:
            completed = self._complete_bucket(self._bucket_key, self._bucket_bars)
            self._bucket_bars = {}
            self._bucket_key = bucket_key
            self._bucket_bars[end_time.minute] = minute_bar
            return completed

        if self._bucket_key is None:
            self._bucket_key = bucket_key

        self._bucket_bars[end_time.minute] = minute_bar
        return None

    def _complete_bucket(self, bucket_key, bars):
        if len(bars) != 5:
            return None

        date_value, bucket_end = bucket_key
        expected_minutes = {
            (bucket_end - offset) % 60 for offset in range(5)
        }

        if set(bars.keys()) != expected_minutes:
            return None

        ordered_bars = sorted(
            bars.values(),
            key=lambda bar: bar.EndTime
        )

        return TradeBar(
            ordered_bars[0].Time,
            self.spy,
            ordered_bars[0].Open,
            max(bar.High for bar in ordered_bars),
            min(bar.Low for bar in ordered_bars),
            ordered_bars[-1].Close,
            sum(bar.Volume for bar in ordered_bars),
            timedelta(minutes=5)
        )

    def _evaluate_crossover_entry(self, data, five_minute_bar):
        end_time = five_minute_bar.EndTime
        if end_time.date() != self.Time.date():
