            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _evaluate_option_exit(self, data):
        if not self._has_option_position() or self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._liquidate_option("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day and
            self.Time.hour > 15 or
            current_date == previous_trading_day and
            self.Time.hour == 15 and self.Time.minute >= 45
        ):
            if self.time_stop_date != current_date:
                self.time_stop_date = current_date
                self._liquidate_option("expiration time stop")
            return

        if self.entry_price is None:
            return

        contract = None
        for chain in data.OptionChains.Values:
            if self.entry_symbol in chain.Contracts:
                contract = chain.Contracts[self.entry_symbol]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._liquidate_option("profit target")

    def _liquidate_option(self, reason):
        if self.entry_symbol is None:
            return

        if self._order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing with liquidation market order")

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.entry_symbol,
                -quantity
            )
            self.Debug(f"Exit submitted ({reason}): {self.entry_symbol}")

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.entry_symbol} "
                    f"at {self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.Debug("Entry order canceled or invalid.")

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {self.entry_symbol}")
            self.exit_ticket = None
            self.entry_ticket = None
            self.entry_symbol = None
            self.entry_price = None

        if getattr(order_event, "IsAssignment", False) or getattr(
            order_event, "IsExercise", False
        ):
            self.Debug("Unexpected option exercise or assignment.")
            self.no_entry_date = self.Time.date()
            self._handle_unexpected_spy_position()

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected option assignment.")
        self.no_entry_date = self.Time.date()
        self._handle_unexpected_spy_position()

    def _handle_expiration_processing(self):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date and self._has_option_position():
            self.no_entry_date = self.Time.date()
            self._liquidate_option("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating.")
            self.no_entry_date = self.Time.date()
            self.MarketOrder(self.spy, -quantity)

    def _has_option_position(self):
        return (
            self.entry_symbol is not None and
            self.Portfolio[self.entry_symbol].Quantity != 0
        )

    def _entry_order_open(self):
        return self._order_open(self.entry_ticket)

    def _order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

