        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, self.consolidator)

        self.pending_signal_time = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None
        self.no_entry_date = None

        # The prompt does not specify a numeric target; this is configurable.
        self.profit_target_multiple = 1.20

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast_ready = self.fast.IsReady
        previous_slow_ready = self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_fast_ready else None
        previous_slow = self.slow.Current.Value if previous_slow_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (previous_fast_ready and previous_slow_ready):
            return
        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bar_time = bar.EndTime.time()
        if bar_time < time(9, 45) or bar_time > time(14, 30):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        current_date = self.Time.date()

        # Immediately handle unexpected SPY equity created by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy.Symbol].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected exercise/assignment: liquidating SPY equity position."
            )
            self.MarketOrder(
                self.spy.Symbol,
                -spy_quantity,
                tag="Unexpected exercise or assignment"
            )
            self.no_entry_date = current_date

        if self.held_option is not None:
            self.ManageHeldOption(slice)
            return

        if self.pending_signal_time is None:
            return

        signal_time = self.pending_signal_time
        self.pending_signal_time = None

        if self.no_entry_date == current_date:
            return

        if self.entry_ticket is not None:
            return

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            self.Debug("Skipped entry: no current SPY bar.")
            return

        chains = list(slice.OptionChains)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                if contract.Expiry.date() >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(c.Expiry.date() for c in contracts)
        target_strike = 1.01 * spy_bar.Close

        eligible = [
            c for c in contracts
            if c.Expiry.date() == selected_expiry
            and c.Right == OptionRight.Call
            and c.Strike >= target_strike
        ]

        if not eligible:
            self.Debug("Skipped entry: no eligible call at selected expiration.")
            return

        selected = min(
            eligible,
