from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    PROFIT_TARGET_PCT = 0.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda u: u.IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.minute_bucket = None
        self.minute_bars = {}

        self.latest_chain = []
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if slice.OptionChains.ContainsKey(self.spy_option.Symbol):
            self.latest_chain = list(slice.OptionChains[self.spy_option.Symbol])
        else:
            self.latest_chain = []

        self._handle_unexpected_spy_position(current_date)
        self._handle_expiration_processing(current_date)
        self._evaluate_held_option_exit(current_date)

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        self._update_five_minute_bar(bar)

    def _update_five_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        session_date = end_time.date()
        minute_of_day = end_time.hour * 60 + end_time.minute

        if minute_of_day < 9 * 60 + 31 or minute_of_day > 16 * 60:
            return

        bucket_end_minute = ((minute_of_day + 4) // 5) * 5
        bucket_end = (
            session_date,
            bucket_end_minute
        )

        if self.minute_bucket is not None and bucket_end != self.minute_bucket:
            self._complete_bucket(self.minute_bucket)

            if bucket_end[0] != self.minute_bucket[0]:
                self.minute_bars = {}

        if self.minute_bucket != bucket_end:
            self.minute_bucket = bucket_end
            self.minute_bars = {}

        self.minute_bars[minute_of_day] = minute_bar

    def _complete_bucket(self, bucket):
        session_date, bucket_end_minute = bucket
        required_minutes = range(bucket_end_minute - 4, bucket_end_minute + 1)

        if not all(minute in self.minute_bars for minute in required_minutes):
            self.minute_bars = {}
            return

        bars = [self.minute_bars[minute] for minute in required_minutes]
        close = bars[-1].Close

        self.closes.append(float(close))
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            self.minute_bars = {}
            return

        previous_closes = self.closes[:-1]
        current_closes = self.closes

        previous_fast = sum(previous_closes[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous_closes[-self.slow_period:]) / self.slow_period
        current_fast = sum(current_closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(current_closes[-self.slow_period:]) / self.slow_period

        bar_end = datetime(
            session_date.year,
            session_date.month,
            session_date.day,
            bucket_end_minute // 60,
            bucket_end_minute % 60
        )

        eligible_time = (
            bar_end.hour > 9 or
            (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or
            (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self._try_enter_call(close, session_date)

        self.minute_bars = {}

    def _try_enter_call(self, spy_price, current_date):
        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if not self.latest_chain:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in self.latest_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in self.latest_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiry,
                float(selected.Strike)
            )
        )

    def _evaluate_held_option_exit(self, current_date):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiry_date = self.held_expiry
        time_stop = False

        if expiry_date is not None:
            previous_trading_day = (
                self.Securities[self.spy]
                .Exchange
                .Hours
                .GetPreviousTradingDay(expiry_date)
            )

            time_stop = (
                current_date == previous_trading_day.date()
                and self.Time.hour == 15
                and self.Time.minute >= 45
            )

        if time_stop:
            self._submit_option_exit("Expiration-eve time stop")
            return

        contract = self._find_current_contract(self.held_option)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_fill_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target_price:
            self._submit_option_exit("Profit target reached")

    def _handle_expiration_processing(self, current_date):
        if self.held_option is None or self.held_expiry is None:
            return

        if current_date >= self.held_expiry:
            self.no_entry_date = current_date
            self._submit_option_exit("Expiration processing liquidation")

    def _handle_unexpected_spy_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.no_entry_date = current_date
        self.Debug(
            "Unexpected SPY exercise or assignment position detected; liquidating."
        )
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -holding.Quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted for {}: {}".format(self.held_option, reason)
        )

    def _find_current_contract(self, symbol):
        for contract in self.latest_chain:
            if contract.Symbol == symbol:
                return contract
        return None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        terminal_statuses = {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        }
        return ticket.Status not in terminal_statuses

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.entry_fill_price = float(order_event.FillPrice)
                self.held_option = order_event.Symbol
                self.held_expiry = self.Securities[order_event.Symbol].Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self.entry_fill_price
                    )
                )

            if order_event.Status in {
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in {
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {}".format(order_event.Symbol))

                self.exit_ticket = None

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_option = None
                    self.held_expiry = None
                    self.entry_fill_price = None

