    def _try_enter_call(self, spy_price, current_date):
        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if not self.latest_chain:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in self.latest_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = float(spy_price) * 1.01

        candidates = [
            contract for contract in self.latest_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol,
                selected_expiry,
                float(selected.Strike)
            )
        )

