        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiry_date = self.held_expiry
        time_stop = False

        if expiry_date is not None:
            previous_trading_day = (
                self.Securities[self.spy]
                .Exchange
                .Hours
                .GetPreviousTradingDay(expiry_date)
            )

            time_stop = (
                current_date == previous_trading_day.date()
                and self.Time.hour == 15
                and self.Time.minute >= 45
            )

        if time_stop:
            self._submit_option_exit("Expiration-eve time stop")
            return

        contract = self._find_current_contract(self.held_option)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_fill_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target_price:
            self._submit_option_exit("Profit target reached")

    def _handle_expiration_processing(self, current_date):
        if self.held_option is None or self.held_expiry is None:
            return

        if current_date >= self.held_expiry:
            self.no_entry_date = current_date
            self._submit_option_exit("Expiration processing liquidation")

    def _handle_unexpected_spy_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.no_entry_date = current_date
        self.Debug(
            "Unexpected SPY exercise or assignment position detected; liquidating."
        )
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -holding.Quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted for {}: {}".format(self.held_option, reason)
        )

    def _find_current_contract(self, symbol):
        for contract in self.latest_chain:
            if contract.Symbol == symbol:
                return contract
        return None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        terminal_statuses = {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        }
        return ticket.Status not in terminal_statuses

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.FillQuantity > 0:
                self.entry_fill_price = float(order_event.FillPrice)
                self.held_option = order_event.Symbol
                self.held_expiry = self.Securities[order_event.Symbol].Symbol.ID.Date.date()

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self.entry_fill_price
                    )
                )

            if order_event.Status in {
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status in {
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            }:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {}".format(order_event.Symbol))

                self.exit_ticket = None

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_option = None
                    self.held_expiry = None
