        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None

        # The specification does not provide a numeric target; this is the
        # configurable default profit target.
        self.profit_target_multiple = 1.20
        self.no_entry_date = None

    def OnData(self, data: Slice):
        now = self._ny_time(self.Time)
        today = now.date()

        self._handle_assignment_or_exercise(today)

        if self.held_symbol is not None:
            expiration = self._expiration_date(self.held_symbol)

            if expiration is not None and today >= expiration:
                self.no_entry_date = today
                self._submit_exit("expiration")
            elif (
                expiration is not None
                and today == expiration - timedelta(days=1)
                and now.time() >= time(15, 45)
            ):
                self._submit_exit("time stop")
            else:
                self._check_profit_target(data)

        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        bar_time = self._ny_time(minute_bar.Time)

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return

        self._process_minute_bar(minute_bar, data)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    "Entry filled: {} at {:.2f}".format(
                        self.held_symbol, self.entry_price
                    )
                )

        elif order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.2f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None

