        local_time = self._ny_time(minute_bar.Time)
        bucket_start = local_time.replace(
            minute=(local_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._finish_bucket(data)
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(minute_bar)

    def _finish_bucket(self, data):
        if self.bucket_start is None:
            return

        bars = sorted(self.bucket_bars, key=lambda x: x.Time)
        if len(bars) != 5:
            self.bucket_bars = []
            return

        times = [self._ny_time(bar.Time) for bar in bars]
        expected = self.bucket_start

        for bar_time in times:
            if bar_time != expected:
                self.bucket_bars = []
                return
            expected += timedelta(minutes=1)

        close_time = self.bucket_start + timedelta(minutes=5)
        if close_time.time() < time(9, 35) or close_time.time() > time(16, 0):
            self.bucket_bars = []
            return

        close_price = bars[-1].Close
        self.fast_window.append(close_price)
        self.slow_window.append(close_price)

        current_fast = None
        current_slow = None

        if len(self.fast_window) == 5:
            current_fast = sum(self.fast_window) / 5.0
        if len(self.slow_window) == 20:
            current_slow = sum(self.slow_window) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        if bullish and time(9, 45) <= close_time.time() <= time(14, 30):
            self._try_entry(data, close_price, close_time.date())

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.bucket_bars = []

