        if self.no_entry_date == signal_date:
            return

        if self.held_symbol is not None or self.entry_order_id is not None:
            return

        chains = list(data.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        if not contracts:
            self.Debug("Skipped entry: option chain contained no contracts.")
            return

        minimum_expiration = signal_date + timedelta(days=7)
        eligible_dates = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not eligible_dates:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiration = eligible_dates[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no suitable call at expiration {}.".format(
                    selected_expiration
                )
            )
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, data):
        if (
            self.held_symbol is None
            or self.entry_price is None
            or self.entry_order_id is not None
        ):
            return

        contract = None
        for chain in data.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiple:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            self.Transactions.CancelOrder(self.exit_order_id)
            self.exit_order_id = None

        self.exit_order_id = self.MarketOrder(
            self.held_symbol,
            -quantity
        ).OrderId
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def _handle_assignment_or_exercise(self, today):
        if self.spy not in self.Portfolio:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                "Unexpected SPY position from exercise or assignment: {}".format(
                    quantity
                )
            )
            self.no_entry_date = today
            self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy, -quantity)

    def _expiration_date(self, symbol):
        security = self.Securities[symbol] if symbol in self.Securities else None
        if security is None:
            return None

        if hasattr(security, "Expiry"):
            return security.Expiry.date()

        return None

    def _ny_time(self, value):
        if value.tzinfo is None:
            return self.ny.localize(value)
        return value.astimezone(self.ny)

