from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyBullishCallCrossover(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.current_bar_end = None
        self.current_bar_values = {}

        self.held_symbol = None
        self.held_expiry = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_block_date = None
        self.logged_equity_assignment = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration_and_time_stop()

        bar = slice.Bars.get(self.spy)
        completed_five_minute_bar = None

        if bar is not None:
            completed_five_minute_bar = self._update_five_minute_builder(bar)

        if completed_five_minute_bar is not None:
            self._process_crossover(completed_five_minute_bar, slice)

        self._evaluate_profit_target(slice)

    def _update_five_minute_builder(self, minute_bar):
        end_time = minute_bar.EndTime
        if hasattr(end_time, "replace"):
            end_time = end_time.replace(tzinfo=None)

        local_date = end_time.date()
        session_start = datetime(
            local_date.year, local_date.month, local_date.day, 9, 30
        )
        session_end = datetime(
            local_date.year, local_date.month, local_date.day, 16, 0
        )

        if end_time <= session_start or end_time > session_end:
            return None

        minutes_from_open = int((end_time - session_start).total_seconds() // 60)
        if minutes_from_open <= 0:
            return None

        endpoint_minutes = ((minutes_from_open + 4) // 5) * 5
        endpoint = session_start + timedelta(minutes=endpoint_minutes)
        expected_times = {
            endpoint - timedelta(minutes=i) for i in range(5)
        }

        completed = None

        if self.current_bar_end is not None and endpoint != self.current_bar_end:
            if set(self.current_bar_values.keys()) == {
                self.current_bar_end - timedelta(minutes=i) for i in range(5)
            }:
                completed = TradeBar(
                    self.current_bar_end - timedelta(minutes=5),
                    self.spy,
                    self.current_bar_values[
                        self.current_bar_end - timedelta(minutes=5)
                    ].Open,
                    max(
                        v.High for v in self.current_bar_values.values()
                    ),
                    min(
                        v.Low for v in self.current_bar_values.values()
                    ),
                    self.current_bar_values[self.current_bar_end].Close,
                    sum(
                        v.Volume for v in self.current_bar_values.values()
                    ),
                    timedelta(minutes=5)
                )

            self.current_bar_values = {}

        if self.current_bar_end != endpoint:
            self.current_bar_end = endpoint

        self.current_bar_values[end_time] = minute_bar

        if completed is not None:
            return completed

        return None

    def _process_crossover(self, bar, slice):
        close = float(bar.Close)

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > self.FAST_PERIOD:
            self.fast_values.pop(0)
        if len(self.slow_values) > self.SLOW_PERIOD:
            self.slow_values.pop(0)

        if (
            len(self.fast_values) < self.FAST_PERIOD
            or len(self.slow_values) < self.SLOW_PERIOD
        ):
            return

        fast = sum(self.fast_values) / self.FAST_PERIOD
        slow = sum(self.slow_values) / self.SLOW_PERIOD

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime
        if hasattr(bar_end, "replace"):
            bar_end = bar_end.replace(tzinfo=None)

        eligible_time = (
            bar_end.hour > 9
            or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if (
            bullish_cross
            and eligible_time
            and self.held_symbol is None
            and self.entry_order_id is None
            and self.expiration_block_date != self.Time.date()
        ):
            self._try_enter(slice)

    def _try_enter(self, slice):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            spy_price = float(spy_bar.Close)
        else:
            spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price
        strike_candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not strike_candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_order_id = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        ).OrderId

    def _evaluate_profit_target(self, slice):
        if self.held_symbol is None or self.entry_fill_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0 or self.exit_order_id is not None:
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_fill_price * self.PROFIT_TARGET_MULTIPLE

        if midpoint >= target:
            self._submit_exit("Profit target reached.")

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        current_date = self.Time.date()
        current_time = self.Time.time()

        if current_date >= self.held_expiry:
            self.expiration_block_date = current_date
            self._submit_exit("Expiration processing liquidation.")
            return

        if (
            current_date == self.held_expiry - timedelta(days=1)
            and current_time >= datetime.min.time().replace(
                hour=15, minute=45
            )
        ):
            self._submit_exit("Pre-expiration time stop.")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Id != self.entry_order_id:
                self.CancelOrder(order.Id, "Cancel competing exit order.")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_order_id = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        ).OrderId

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            if not self.logged_equity_assignment:
                self.Debug(
                    "Unexpected SPY equity position detected; liquidating immediately."
                )
                self.logged_equity_assignment = True

            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment handling"
            )
        else:
            self.logged_equity_assignment = False

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            if (
                self.entry_order_id == order_event.OrderId
                and order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_
                )
            ):
                self.entry_order_id = None
            return

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")
            spy_quantity = self.Portfolio[self.spy].Quantity
            if spy_quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Unexpected exercise or assignment handling"
                )

        if order_event.OrderId == self.entry_order_id:
            self.held_symbol = order_event.Symbol
            self.entry_fill_price = float(order_event.FillPrice)
            self.held_expiry = order_event.Symbol.ID.Date.date()
            self.entry_order_id = None

            self.Debug(
                "Entered 1 SPY call: {0}, fill {1:.4f}".format(
                    self.held_symbol, self.entry_fill_price
                )
            )

        elif order_event.OrderId == self.exit_order_id:
            self.Debug(
                "Exited SPY call: {0}, fill {1:.4f}".format(
                    order_event.Symbol, float(order_event.FillPrice)
                )
            )
            self.exit_order_id = None
            self.held_symbol = None
            self.held_expiry = None
            self.entry_fill_price = None
        elif order_event.OrderType == OrderType.OptionExercise:
            self.Debug("Unexpected option exercise or assignment handling.")

