        self._process_held_option(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar, slice):
        end_time = bar.EndTime
        local_date = end_time.date()
        local_time = end_time.time()

        if local_time < datetime.strptime("09:31", "%H:%M").time():
            return
        if local_time > datetime.strptime("16:00", "%H:%M").time():
            return

        remainder = end_time.minute % 5
        boundary = end_time + timedelta(minutes=(5 - remainder) % 5)
        boundary = boundary.replace(second=0, microsecond=0)

        bucket = self.minute_buffer.setdefault(boundary, {})
        bucket[end_time] = bar

        if end_time.minute % 5 != 0:
            return

        if boundary in self.processed_boundaries:
            return

        self.processed_boundaries.add(boundary)

        expected_times = [
            boundary - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(timestamp not in bucket for timestamp in expected_times):
            self.minute_buffer.pop(boundary, None)
            return

        bars = [bucket[timestamp] for timestamp in reversed(expected_times)]
        self.minute_buffer.pop(boundary, None)

        consolidated = TradeBar(
            boundary - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if previous_fast is None or previous_slow is None:
            return

        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if not (eligible_start <= boundary.time() <= eligible_end):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self._try_enter(slice, consolidated.Close)

    def _try_enter(self, slice, spy_price):
        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self._entry_order_is_open():
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: {}".format(selected.Symbol))

    def _process_held_option(self, slice):
        if self.held_option is None:
            return

        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.no_entry_today = True
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("expiration time stop")
            return

        if symbol not in slice.OptionQuotes:
            return

        quote = slice.OptionQuotes[symbol]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.TARGET_PROFIT_PCT)

        if midpoint >= target:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Option exit submitted: {}".format(reason))

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            return

        if (
            self.assignment_liquidation_ticket is None
            or not self._order_is_open(self.assignment_liquidation_ticket)
        ):
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment"
            )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self._order_is_open(self.entry_ticket)
        )

    def _order_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")
            self._handle_unexpected_spy_position()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Option exit filled: {}".format(order_event.Symbol))
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

