    def _process_minute_bar(self, bar: TradeBar):
        local_time = bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if not (time(9, 30) <= local_time.time() < time(16, 0)):
            return

        bucket_start = local_time.replace(
            minute=(local_time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start != bucket_start:
            if self.bucket_start is not None:
                self._finalize_bucket()

            self.bucket_start = bucket_start
            self.bucket_bars = []

        if self.bucket_bars:
            previous = self.bucket_bars[-1].Time
            if local_time != previous + timedelta(minutes=1):
                self.bucket_bars = [bar]
                return

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._finalize_bucket()
            self.bucket_start = None
            self.bucket_bars = []

    def _finalize_bucket(self):
        if self.bucket_start is None or len(self.bucket_bars) != 5:
            return

        expected = self.bucket_start
        for bar in self.bucket_bars:
            if bar.Time != expected:
                return
            expected += timedelta(minutes=1)

        consolidated = TradeBar(
            self.bucket_start,
            self.spy,
            self.bucket_bars[0].Open,
            max(bar.High for bar in self.bucket_bars),
            min(bar.Low for bar in self.bucket_bars),
            self.bucket_bars[-1].Close,
            sum(bar.Volume for bar in self.bucket_bars),
            timedelta(minutes=5)
        )

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(consolidated.EndTime, consolidated.Close)
        self.slow.Update(consolidated.EndTime, consolidated.Close)

        if previous_fast is None or previous_slow is None:
            return
        if not (self.fast.IsReady and self.slow.IsReady):
            return

        bar_end = consolidated.EndTime.time()
        if time(9, 45) <= bar_end <= time(14, 30):
            if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
                self.pending_signal = consolidated

    def _try_enter(self, slice: Slice, signal_bar: TradeBar):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            return

        if self._has_open_entry_order():
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: no current SPY bar.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry = contract.Expiry.date()
                if contract.Right != OptionRight.Call:
                    continue
                contracts.append(contract)

        minimum_expiry = current_date + timedelta(days=7)
        valid_expiries = sorted(
            {contract.Expiry.date() for contract in contracts
             if contract.Expiry.date() >= minimum_expiry}
        )

        if not valid_expiries:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiry={} strike={}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity == 0:
            return

        if self._is_expiration_processing_day():
            self._submit_exit("expiration")
            return

        if self._is_time_stop_day() and self.Time.time() >= time(15, 45):
            self._submit_exit("time stop")
            return

        if self.profit_target is None or self.held_symbol not in slice.OptionChains:
            quote = self._get_option_quote(slice, self.held_symbol)
            if quote is None:
                return
            bid, ask = quote
        else:
            quote = self._get_option_quote(slice, self.held_symbol)
            if quote is None:
                return
            bid, ask = quote

        midpoint = (bid + ask) / 2
        if midpoint >= self.profit_target:
            self._submit_exit("profit target")

    def _get_option_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    return bid, ask
                return None
        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted: {} ({})".format(self.held_symbol, reason))

    def _handle_expiration_processing(self):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.blocked_entry_date = self.Time.date()
            self._submit_exit("expiration processing")

    def _is_time_stop_day(self):
        if self.held_symbol is None:
            return False

        expiry = self.held_symbol.ID.Date.date()
        previous_trading_day = expiry - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime.combine(previous_trading_day, time(0, 0))
        ):
            previous_trading_day -= timedelta(days=1)

        return self.Time.date() == previous_trading_day

    def _is_expiration_processing_day(self):
        if self.held_symbol is None:
            return False
        return self.Time.date() >= self.held_symbol.ID.Date.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        event_type = str(order_event.OrderEventType)

        if "Exercise" in event_type or "Assignment" in event_type:
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment handled.")

            spy_holding = self.Portfolio[self.spy]
            if spy_holding.Quantity != 0:
                self.MarketOrder(self.spy, -spy_holding.Quantity)
                self.Debug("Liquidated unexpected SPY equity position.")

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.profit_target = self.entry_price * self.PROFIT_TARGET_MULTIPLE
                self.Debug(
                    "Entry filled: {} at {:.2f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self.held_symbol))
                self.held_symbol = None
                self.entry_price = None
                self.profit_target = None
                self.exit_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0 and self.held_symbol is None:
            self.blocked_entry_date = self.Time.date()
            self.MarketOrder(self.spy, -holding.Quantity)
            self.Debug("Liquidated unexpected SPY equity position.")

    def _update_entry_order_state(self):
        if self.entry_ticket is None:
            return

        if self.entry_ticket.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Filled,
        ):
            if self.entry_ticket.Status != OrderStatus.Filled:
                self.entry_ticket = None

    def _has_open_entry_order(self):
        return self._ticket_is_open(self.entry_ticket)

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

