from collections import deque
from datetime import datetime, timedelta, time

from AlgorithmImports import *


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self._bucket_start = None
        self._bucket_bars = []
        self._bucket_valid = True

        self._latest_slice = None
        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_fill_price = None
        self._blocked_entry_date = None
        self._equity_liquidation_ticket = None

        # Configurable through the LEAN parameter "ProfitTargetPercent".
        target = self.GetParameter("ProfitTargetPercent")
        self.profit_target_percent = float(target) if target else 50.0

    def OnData(self, slice: Slice):
        self._latest_slice = slice
        today = self.Time.date()

        self._liquidate_unexpected_spy_position()
        self._process_option_expiration(today)
        self._process_option_exit(slice, today)

        if self.spy.Symbol in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy.Symbol])

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        bar_time = minute_bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minute = bar_time.minute
        bucket_minute = 30 + ((minute - 30) // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute, second=0, microsecond=0
        )

        if self._bucket_start is None:
            self._start_bucket(bucket_start)
        elif bucket_start != self._bucket_start:
            self._finish_bucket()
            self._start_bucket(bucket_start)

        if self._bucket_bars:
            expected_time = self._bucket_bars[-1].Time + timedelta(minutes=1)
            if bar_time != expected_time:
                self._bucket_valid = False

        self._bucket_bars.append(minute_bar)

        if len(self._bucket_bars) > 5:
            self._bucket_valid = False

    def _start_bucket(self, bucket_start):
        self._bucket_start = bucket_start
        self._bucket_bars = []
        self._bucket_valid = True

    def _finish_bucket(self):
        if self._bucket_start is None:
            return

        if self._bucket_valid and len(self._bucket_bars) == 5:
            close = self._bucket_bars[-1].Close
            self._evaluate_completed_bar(
                self._bucket_start + timedelta(minutes=5),
                close
            )

        self._bucket_start = None
        self._bucket_bars = []
        self._bucket_valid = True

    def _evaluate_completed_bar(self, bar_end_time, close):
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            self.previous_fast = (
                sum(self.fast_closes) / len(self.fast_closes)
                if len(self.fast_closes) == 5 else None
            )
            self.previous_slow = (
                sum(self.slow_closes) / len(self.slow_closes)
                if len(self.slow_closes) == 20 else None
            )
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_end_clock = bar_end_time.time()
        eligible = time(9, 45) <= bar_end_clock <= time(14, 30)

        if crossover and eligible:
            self._try_enter_call()

    def _try_enter_call(self):
        today = self.Time.date()

        if self._blocked_entry_date == today:
            return

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None and self._is_open_ticket(self._entry_ticket):
            return

        if self._latest_slice is None or not self._latest_slice.OptionChains:
            self.Debug("Skipped call selection: no option chain.")
            return

        spy_price = None
        if self.spy.Symbol in self._latest_slice.Bars:
