        self.entry_price = None
        self.blocked_entry_date = None

        # Can be overridden with a QC parameter named ProfitTargetPercent.
        self.profit_target_percent = float(
            self.GetParameter("ProfitTargetPercent") or 20
        ) / 100.0

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.EvaluateOptionExit(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        local_end = bar.EndTime.astimezone(self.TimeZone)
        end_time = local_end.time()

        if end_time < time(9, 45) or end_time > time(14, 30):
            eligible = False
        else:
            eligible = True

        if self.fast_window.IsReady and self.slow_window.IsReady:
            previous_fast = sum(self.fast_window) / self.fast_window.Count
            previous_slow = sum(self.slow_window) / self.slow_window.Count
        else:
            previous_fast = None
            previous_slow = None

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not (eligible and self.fast_window.IsReady and self.slow_window.IsReady):
            return

        current_fast = sum(self.fast_window) / self.fast_window.Count
        current_slow = sum(self.slow_window) / self.slow_window.Count

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross:
            self.TryEnterCall(bar.Close)

    def TryEnterCall(self, spy_price: float):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket.Status):
            return

        if self.current_slice is None or not self.current_slice.OptionChains:
            self.Debug("Skipped call selection: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in self.current_slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no qualifying expiration")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * float(spy_price)
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def EvaluateOptionExit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_option.ID.Date.date()
        today = self.Time.date()
        local_time = self.Time.time()

        if today >= expiry_date:
            self.SubmitOptionExit("expiration processing")
            return

        previous_trading_day = self.PreviousTradingDay(expiry_date)
        if (
            today == previous_trading_day
            and local_time >= time(15, 45)
        ):
            self.SubmitOptionExit("pre-expiration time stop")
            return

        if not slice.QuoteBars.ContainsKey(self.held_option):
            return

        quote = slice.QuoteBars[self.held_option]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.profit_target_percent)

        if midpoint >= target:
            self.SubmitOptionExit("profit target")

    def SubmitOptionExit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket.Status):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.CancelOpenExitOrder()
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag="Call exit: " + reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(self.held_option, reason)
        )

    def HandleExpirationProcessing(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            self.SubmitOptionExit("expiration processing")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.Debug(
            "Unexpected SPY exercise or assignment position detected; liquidating"
        )
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
        self.blocked_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    if order_event.FillQuantity > 0:
                        self.held_option = order_event.Symbol
                        self.entry_price = float(order_event.FillPrice)
                        self.Debug(
                            "Call entry filled: {0} at {1}".format(
                                self.held_option, self.entry_price
                            )
                        )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    if (
                        self.held_option is not None
                        and self.Portfolio[self.held_option].Quantity == 0
                    ):
                        self.Debug(
                            "Call exit filled: {0}".format(order_event.Symbol)
                        )
                        self.held_option = None
                        self.entry_price = None
                        self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

    def CancelOpenExitOrder(self):
        if (
            self.exit_ticket is not None
            and self.IsOpen(self.exit_ticket.Status)
        ):
            self.exit_ticket.Cancel("Superseded by another exit")

    def IsOpen(self, status):
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate.strftime(
            "%Y-%m-%d"
        ) and candidate

