from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(0), timedelta(days=730))
        )
        self.option_symbol = self.spy_option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = deque(maxlen=self.fast_period)
        self.slow_values = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.profit_target_percent = 0.20
        self.blocked_entry_date = None

    def OnData(self, slice):
        today = self.Time.date()

        self._handle_unexpected_equity_position()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.blocked_entry_date = today
                self._submit_exit("expiration processing")
            elif today == expiry_date - timedelta(days=1):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self._submit_exit("pre-expiration time stop")
            else:
                self._evaluate_profit_target(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        completed_bar = self._add_minute_bar(bar)
        if completed_bar is None:
            return

        signal = self._update_averages(completed_bar)
        if not signal:
            return

        bar_end = self._local_time(completed_bar.EndTime)
        if not (
            (bar_end.hour == 9 and bar_end.minute >= 45)
            or (10 <= bar_end.hour <= 13)
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        ):
            return

        if today == self.blocked_entry_date:
            return

        if self.held_option is not None or self._entry_order_open():
            return

        self._enter_from_chain(slice, today)

    def _local_time(self, value):
        return self.TimeZone.ConvertFromUtc(value)

    def _add_minute_bar(self, bar):
        local_start = self._local_time(bar.Time)
        local_date = local_start.date()

        if local_start.weekday() >= 5:
            return None

        minutes_from_open = (
            local_start.hour * 60 + local_start.minute
        ) - (9 * 60 + 30)

        if minutes_from_open < 0 or minutes_from_open >= 390:
            return None

        bucket_minute = 9 * 60 + 30 + (minutes_from_open // 5) * 5
        bucket_start = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        if self.current_bucket_start != bucket_start:
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = []

        self.current_bucket_bars.append(bar)

        if len(self.current_bucket_bars) < 5:
            return None

        bars = self.current_bucket_bars
        self.current_bucket_bars = []

        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]
        actual_times = [
            self._local_time(item.Time).replace(tzinfo=None) for item in bars
        ]

        if actual_times != expected_times:
            return None

        return TradeBar(
            Symbol=self.spy,
            Time=bars[0].Time,
            EndTime=bars[-1].EndTime,
            Open=bars[0].Open,
            High=max(item.High for item in bars),
            Low=min(item.Low for item in bars),
            Close=bars[-1].Close,
            Volume=sum(item.Volume for item in bars),
            Value=sum(item.Value for item in bars)
        )

    def _update_averages(self, bar):
        if len(self.slow_values) == self.slow_period:
            previous_fast = self.previous_fast
            previous_slow = self.previous_slow
        else:
            previous_fast = None
            previous_slow = None

        self.fast_values.append(bar.Close)
        self.slow_values.append(bar.Close)

        if len(self.slow_values) < self.slow_period:
            self.previous_fast = None
            self.previous_slow = None
            return False

        current_fast = sum(list(self.slow_values)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.slow_values) / self.slow_period

        signal = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        return signal

    def _enter_from_chain(self, slice, current_date):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = list(chain)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration at least 7 days away")
            return

        selected_expiry = expiries[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _evaluate_profit_target(self, slice):
        if self.entry_price is None or self.exit_ticket is not None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        target = self.entry_price * (1 + self.profit_target_percent)

        if midpoint >= target:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        self.Transactions.CancelOpenOrders(self.held_option)
        quantity = self.Portfolio[self.held_option].Quantity

        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity
            )
            self.Debug(
                "Exit submitted ({0}): {1}".format(reason, self.held_option)
            )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY position"
            )
            self.MarketOrder(self.spy, -quantity)
            self.blocked_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and (
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                self.Debug("Entry order did not fill")
                self.entry_ticket = None

        if self.exit_ticket is not None and (
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(order_event.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment received")
        self.blocked_entry_date = self.Time.date()
        self._handle_unexpected_equity_position()

